window.__NLM_CHAPS = window.__NLM_CHAPS || {};
window.__NLM_CHAPS["reading"] = "<section class=\"chapter-section\" id=\"reading\">\n  <h2 class=\"chapter-title\">Bab 3: Pemahaman Bacaan (<ruby>\u7b2c<rt>\u3060\u3044</rt></ruby>3<ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby> <ruby>\u8aad<rt>\u3069\u3063</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby> / Dokkai)</h2>\n\n  <!-- ==================== BAGIAN 1: TIPS & TRIK ==================== -->\n  <div class=\"sub-section\" id=\"reading-tips\">\n    <h3>1. Tips &amp; Trik Menjawab Soal Pemahaman Bacaan (<ruby>\u8aad<rt>\u3069\u3063</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3092<ruby>\u89e3<rt>\u3068</rt></ruby>\u304f\u30b3\u30c4)</h3>\n\n    <div class=\"info-box\">\n      <h4>Format Soal JLPT N3 Pemahaman Bacaan</h4>\n      <p>\n        <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306e<ruby>\u5f62<rt>\u3051\u3044</rt></ruby><ruby>\u5f0f<rt>\u3057\u304d</rt></ruby>\u306f\u3001<ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u90e8<rt>\u3076</rt></ruby>\u30672<ruby>\u7a2e<rt>\u3057\u3085</rt></ruby><ruby>\u985e<rt>\u308b\u3044</rt></ruby>\u3042\u308a\u307e\u3059\u3002\uff08<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u306f<ruby>\u5909<rt>\u3078\u3093</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby>\u3059\u308b<ruby>\u53ef<rt>\u304b</rt></ruby><ruby>\u80fd<rt>\u306e\u3046</rt></ruby><ruby>\u6027<rt>\u305b\u3044</rt></ruby>\u304c\u3042\u308a\u307e\u3059\u3002\uff09<br>\n        <em>Format soal seluruhnya terdiri dari 2 jenis utama (Pemahaman Isi dan Pencarian Informasi, yang terbagi menjadi 4 bagian soal di bawah ini; jumlah soal dapat berubah sewaktu-waktu):</em>\n      </p>\n      <ul>\n        <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>4\u3000<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u77ed<rt>\u305f\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u30004<ruby>\u554f<rt>\u3082\u3093</rt></ruby></strong> \u00b7 Pemahaman Isi (Teks Pendek): 4 soal</li>\n        <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>5\u3000<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u30006<ruby>\u554f<rt>\u3082\u3093</rt></ruby></strong> \u00b7 Pemahaman Isi (Teks Sedang): 6 soal</li>\n        <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>6\u3000<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u30004<ruby>\u554f<rt>\u3082\u3093</rt></ruby></strong> \u00b7 Pemahaman Isi (Teks Panjang): 4 soal</li>\n        <li><strong><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>7\u3000<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby><ruby>\u691c<rt>\u3051\u3093</rt></ruby><ruby>\u7d22<rt>\u3055\u304f</rt></ruby>\u30002<ruby>\u554f<rt>\u3082\u3093</rt></ruby></strong> \u00b7 Pencarian Informasi: 2 soal</li>\n      </ul>\n    </div>\n\n    <div class=\"info-box\">\n      <h4>Langkah 1. Membaca Kalimat Pertanyaan (1. <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080)</h4>\n      <p>\n        \u307e\u305a\u3001<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u304c\u3069\u306e\u3088\u3046\u306a\u3082\u306e\u304b\u3092<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3057\u307e\u3059\u3002<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u306e<ruby>\u7a2e<rt>\u3057\u3085</rt></ruby><ruby>\u985e<rt>\u308b\u3044</rt></ruby>\u306f3<ruby>\u7a2e<rt>\u3057\u3085</rt></ruby><ruby>\u985e<rt>\u308b\u3044</rt></ruby>\u3042\u308a\u307e\u3059\u3002<br>\n        <em>Pertama-tama, periksa terlebih dahulu seperti apa kalimat pertanyaannya. Ada 3 jenis kalimat pertanyaan dalam soal membaca:</em>\n      </p>\n      <ol>\n        <li>\n          <ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306e<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u306b<ruby>\u5408<rt>\u3042</rt></ruby>\u3046\u3082\u306e\u3092<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3059\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><br>\n          <em>Soal yang menanyakan pendapat atau gagasan yang sesuai dengan pemikiran penulis teks.</em>\n        </li>\n        <li>\n          <ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u56e0<rt>\u3044\u3093</rt></ruby>\u3084<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3092<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3059\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\uff08\uff3f\uff3f\u306f\u306a\u305c\u304b\u3002\uff3f\uff3f\u306f\u3069\u3046\u3057\u3066\u304b\u3002\uff09<br>\n          <em>Soal yang menanyakan sebab atau alasan (Mengapa \uff3f\uff3f? / Kenapa \uff3f\uff3f?).</em>\n        </li>\n        <li>\n          <ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3059\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\uff08\uff3f\uff3f\u306f<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304b\u3002\uff3f\uff3f\u306b\u3064\u3044\u3066<ruby>\u5408<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002\uff09<br>\n          <em>Soal yang menanyakan isi teks (Apakah \uff3f\uff3f itu? / Manakah pernyataan yang benar mengenai \uff3f\uff3f?).</em>\n        </li>\n      </ol>\n    </div>\n\n    <div class=\"info-box\">\n      <h4>Langkah 2. Membaca Teks &amp; Memahami Alurnya (2. <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3001<ruby>\u6d41<rt>\u306a\u304c</rt></ruby>\u308c\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3059\u308b)</h4>\n      <p>\n        <ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u306f<ruby>\u4ee5<rt>\u3044</rt></ruby><ruby>\u4e0b<rt>\u304b</rt></ruby>\u306e3\u3064\u306e\u300c<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u300d\u3067\u3067\u304d\u3066\u3044\u307e\u3059\u3002<br>\n        <em>Sebuah bacaan tersusun dari 3 jenis \"hubungan\" berikut ini:</em>\n      </p>\n      <ol>\n        <li><strong><ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\uff1dB\u3000A\u3068B\u304c<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058</strong> \u00b7 <em>Hubungan Setara/Sama (A = B): A dan B bermakna sama.</em></li>\n        <li><strong><ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\u2194B\u3000A\u3068B\u304c<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby></strong> \u00b7 <em>Hubungan Berlawanan (A \u2194 B): A dan B bertentangan/berlawanan.</em></li>\n        <li><strong><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u30fb<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\u2192B\u3000A\u3060\u304b\u3089B</strong> \u00b7 <em>Hubungan Sebab-Akibat (A \u2192 B): Karena A, maka terjadi B.</em></li>\n      </ol>\n      <p>\n        <ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3001<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3001<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u30fb<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u306b\u306a\u3063\u3066\u3044\u308b\u304b\u3069\u3046\u304b\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u306a\u304c\u3089\u3001<ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3068<ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3001<ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u3068<ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u306e<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3059\u308b\u3053\u3068\u304c<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u756a<rt>\u3070\u3093</rt></ruby><ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3067\u3059\u3002<br>\n        \u2605\u3067\u306f\u3001<ruby>\u8aad<rt>\u3069\u3063</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306e\u3088\u3046\u306a<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306b<ruby>\u898b<rt>\u307f</rt></ruby>\u3066\u307f\u307e\u3057\u3087\u3046\u3002\u3053\u306e3\u3064\u306e<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u306f\u300c<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u300d\u30fb\u300c<ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u300d\u30fb\u300c<ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u300d\u3067\u3082<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002<br>\n        <em>Hal yang terpenting adalah memahami hubungan antara kalimat dengan kalimat serta paragraf dengan paragraf sambil memikirkan apakah hubungan tersebut berupa hubungan setara, hubungan berlawanan, atau hubungan sebab-akibat. Mari kita lihat contoh bacaan seperti pada soal dokkai yang sesungguhnya. Ketiga hubungan ini dapat digunakan pada tingkat \"kata\", \"kalimat\", maupun \"paragraf\".</em>\n      </p>\n    </div>\n\n    <!-- Hubungan 1: Sama -->\n    <div class=\"info-box\">\n      <h4>1. Hubungan Setara / Sama (<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\uff1dB)</h4>\n      <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh Dasar):</strong></p>\n      <p>\n        <u><ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u304c<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u308b<ruby>\u8a00<rt>\u3052\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby></u>(A)\u306f<u><ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby></u>(B)\u3067\u3059\u3002<br>\n        <em><u>Bahasa yang sedang saya pelajari</u> (A) adalah <u>bahasa Jepang</u> (B).</em>\n      </p>\n      <p>\n        <ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u304c<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u308b<ruby>\u8a00<rt>\u3052\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>(A) \uff1d <ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>(B)<br>\n        \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067\u3001\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u304c<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u308b<ruby>\u8a00<rt>\u3052\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u300d\u3068\u300c<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u300d\u306f<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3067\u3059\u3002<br>\n        <em>Di dalam kalimat ini, \"bahasa yang sedang saya pelajari\" dan \"bahasa Jepang\" memiliki hubungan yang sama (setara).</em>\n      </p>\n\n      <p><strong>\u2460 <ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\uff1dB (Mencari Kata yang Sama)</strong></p>\n      <div class=\"reading-passage\">\n        <p><u>\u30b9\u30de\u30db</u>(A)\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f\u3068\u3066\u3082<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002\u3053\u306e<u><ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306a<ruby>\u56db<rt>\u3057</rt></ruby><ruby>\u89d2<rt>\u304b\u304f</rt></ruby>\u3044<ruby>\u7bb1<rt>\u306f\u3053</rt></ruby></u>(B)\u306e\u304a\u304b\u3052\u3067\u3001<ruby>\u9060<rt>\u3068\u304a</rt></ruby>\u304f\u306b<ruby>\u4f4f<rt>\u3059</rt></ruby>\u3093\u3067\u3044\u308b<ruby>\u53cb<rt>\u3086\u3046</rt></ruby><ruby>\u4eba<rt>\u3058\u3093</rt></ruby>\u3068<ruby>\u8a71<rt>\u306f\u306a</rt></ruby>\u3059\u3053\u3068\u3084\u3001<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby>\u3092<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u306f\u3001\u3068\u3066\u3082<ruby>\u7c21<rt>\u304b\u3093</rt></ruby><ruby>\u5358<rt>\u305f\u3093</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Dengan hadirnya <u>ponsel pintar (smartphone)</u> (A), kehidupan masyarakat menjadi sangat praktis. Berkat <u>kotak persegi yang praktis</u> (B) ini, berbicara dengan teman yang tinggal jauh maupun mencari informasi baru menjadi sangat mudah.</p>\n      </div>\n\n      <p><strong>\u2461 <ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\uff1dB (Mencari Kalimat yang Sama)</strong></p>\n      <div class=\"reading-passage\">\n        <p>\u30b9\u30de\u30db\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u304c<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u3063\u305f\u3060\u3051\u3067\u306a\u304f\u3001<u><ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u305f\u3061\u306f\u3082\u3046\u30b9\u30de\u30db\u304c\u306a\u3044\u3068<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u304c\u3067\u304d\u306a\u3044</u>(A)\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u306e<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3001<ruby>\u8a00<rt>\u3052\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u306e<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3001<ruby>\u6b6f<rt>\u306f</rt></ruby><ruby>\u533b<rt>\u3044</rt></ruby><ruby>\u8005<rt>\u3057\u3083</rt></ruby>\u306e<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u7d04<rt>\u3084\u304f</rt></ruby>\u3001<u><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306e<ruby>\u5168<rt>\u3059\u3079</rt></ruby>\u3066\u3092\u30b9\u30de\u30db\u306b<ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u3063\u3066\u3044\u307e\u3059</u>(B)\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Dengan hadirnya ponsel pintar, kehidupan bukan hanya menjadi praktis, melainkan <u>kita sudah tidak bisa hidup tanpa ponsel pintar</u> (A). Mulai dari menghubungi urusan pekerjaan, belajar bahasa, membuat janji dokter gigi, <u>kita mengandalkan seluruh kehidupan pada ponsel pintar</u> (B).</p>\n      </div>\n\n      <p><strong>\u2462 <ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\uff1dB (Mencari Paragraf yang Sama)</strong></p>\n      <div class=\"reading-passage\">\n        <p><u>\u30b9\u30de\u30db\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f\u3068\u3066\u3082<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002\u3069\u3053\u306b\u3044\u3066\u3082<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3092\u3068\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3057\u3001\u308f\u304b\u3089\u306a\u3044\u3053\u3068\u306f\u3044\u3064\u3067\u3082<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002</u>(A)</p>\n        <p><u>\u3053\u306e<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306a<ruby>\u56db<rt>\u3057</rt></ruby><ruby>\u89d2<rt>\u304b\u304f</rt></ruby>\u3044<ruby>\u7bb1<rt>\u306f\u3053</rt></ruby>\u306e\u304a\u304b\u3052\u3067\u3001<ruby>\u9060<rt>\u3068\u304a</rt></ruby>\u304f\u306b<ruby>\u4f4f<rt>\u3059</rt></ruby>\u3093\u3067\u3044\u308b<ruby>\u53cb<rt>\u3086\u3046</rt></ruby><ruby>\u4eba<rt>\u3058\u3093</rt></ruby>\u3068<ruby>\u8a71<rt>\u306f\u306a</rt></ruby>\u3059\u3053\u3068\u3084\u3001<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby>\u3092<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u306f\u3001<ruby>\u6c7a<rt>\u3051\u3063</rt></ruby>\u3057\u3066<ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u3044\u3053\u3068\u3067\u306f\u306a\u304f\u306a\u3063\u305f\u306e\u3067\u3059\u3002</u>(B)</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p><u>Dengan hadirnya ponsel pintar, kehidupan masyarakat menjadi sangat praktis. Di mana pun berada kita dapat menghubungi teman, dan hal yang tidak diketahui pun dapat dicari kapan saja.</u> (A)</p>\n        <p><u>Berkat kotak persegi yang praktis ini, berbicara dengan teman yang tinggal jauh maupun mencari informasi baru tidak lagi menjadi hal yang sulit.</u> (B)</p>\n      </div>\n      <p>\n        <strong>\u203b A\u3068B\u304c<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u306b\u306a\u308b<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby> (Alasan A dan B memiliki hubungan yang sama):</strong><br>\n        1\uff09\u3069\u3053\u306b\u3044\u3066\u3082<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3092\u3068\u308b\u3053\u3068\u304c\u3067\u304d\u308b \uff1d <ruby>\u9060<rt>\u3068\u304a</rt></ruby>\u304f\u306b<ruby>\u4f4f<rt>\u3059</rt></ruby>\u3093\u3067\u3044\u308b<ruby>\u53cb<rt>\u3086\u3046</rt></ruby><ruby>\u4eba<rt>\u3058\u3093</rt></ruby>\u3068<ruby>\u8a71<rt>\u306f\u306a</rt></ruby>\u3059\u3053\u3068<br>\n        <em>(Di mana pun berada dapat menghubungi teman \uff1d Berbicara dengan teman yang tinggal jauh)</em><br>\n        2\uff09\u308f\u304b\u3089\u306a\u3044\u3053\u3068\u306f\u3044\u3064\u3067\u3082<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u308b \uff1d <ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby>\u3092<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u306f\u3001<ruby>\u6c7a<rt>\u3051\u3063</rt></ruby>\u3057\u3066<ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u3044\u3053\u3068\u3067\u306f\u306a\u304f\u306a\u3063\u305f<br>\n        <em>(Hal yang tidak diketahui dapat dicari kapan saja \uff1d Mencari informasi baru tidak lagi menjadi hal yang sulit)</em>\n      </p>\n    </div>\n\n    <!-- Hubungan 2: Berlawanan -->\n    <div class=\"info-box\">\n      <h4>2. Hubungan Berlawanan (<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\u2194B)</h4>\n      <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh Dasar):</strong></p>\n      <p>\n        <u><ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3057\u305f</u>\u3002(A)<br>\n        \u3067\u3082<ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u306f\u3001<u><ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u305b\u3093</u>\u3002(B)<br>\n        <em><u>Dulu saya belajar bahasa Jepang</u>. (A) Tetapi sekarang, <u>saya tidak belajar bahasa Jepang</u>. (B)</em>\n      </p>\n      <p>\n        <ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3057\u305f\u3002(A) \u2194 <ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u305b\u3093\u3002(B)<br>\n        \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067\u3001\u300c<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3057\u305f\u3002\u300d\u3068\u300c<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u305b\u3093\u3002\u300d\u306f\u3001<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3067\u3059\u3002<br>\n        <em>Dalam bacaan ini, \"Dulu saya belajar bahasa Jepang.\" dan \"Saya tidak belajar bahasa Jepang.\" memiliki hubungan yang berlawanan.</em>\n      </p>\n\n      <p><strong>\u2460 <ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2194B (Mencari Kata yang Berlawanan)</strong></p>\n      <div class=\"reading-passage\">\n        <p><u>\u30b9\u30de\u30db</u>(A)\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f\u3068\u3066\u3082<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002\u305d\u306e<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u65b9<rt>\u307d\u3046</rt></ruby>\u3067\u3001\u3044\u3064\u3067\u3082\u30e1\u30fc\u30eb\u3092<ruby>\u9001<rt>\u304a\u304f</rt></ruby>\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u305f\u3081\u3001<u><ruby>\u624b<rt>\u3066</rt></ruby><ruby>\u7d19<rt>\u304c\u307f</rt></ruby></u>(B)\u306f\u3069\u3093\u3069\u3093<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306a\u304f\u306a\u3063\u3066\u304d\u3066\u3044\u307e\u3059\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Dengan hadirnya <u>ponsel pintar</u> (A), kehidupan masyarakat menjadi sangat praktis. Di sisi lain, karena dapat mengirim email kapan saja, <u>surat (kertas)</u> (B) semakin tidak diperlukan lagi.</p>\n      </div>\n\n      <p><strong>\u2461 <ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2194B (Mencari Kalimat yang Berlawanan)</strong></p>\n      <div class=\"reading-passage\">\n        <p>\u30b9\u30de\u30db\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u304c<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u3063\u305f\u3060\u3051\u3067\u306a\u304f\u3001<u><ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u305f\u3061\u306f\u3082\u3046\u30b9\u30de\u30db\u304c\u306a\u3044\u3068<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u304c\u3067\u304d\u306a\u3044\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f</u>(A)\u3002\u3057\u304b\u3057\u3001<ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u305d\u308d\u3063\u3066<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u304f<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3092\u3059\u308b<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby>\u306b\u306f\u3001<u>\u30b9\u30de\u30db\u306f<ruby>\u5168<rt>\u307e\u3063\u305f</rt></ruby>\u304f<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306e\u306a\u3044\u3082\u306e\u3067\u3059</u>(B)\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Dengan hadirnya ponsel pintar, kehidupan bukan hanya menjadi praktis, melainkan <u>kita sudah tidak bisa hidup tanpa ponsel pintar</u> (A). Akan tetapi, pada waktu makan bersama seluruh anggota keluarga dengan gembira, <u>ponsel pintar adalah benda yang sama sekali tidak diperlukan</u> (B).</p>\n      </div>\n\n      <p><strong>\u2462 <ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2194B (Mencari Paragraf yang Berlawanan)</strong></p>\n      <div class=\"reading-passage\">\n        <p><u>\u30b9\u30de\u30db\u306e<ruby>\u767b<rt>\u3068\u3046</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3088\u308a\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f\u3068\u3066\u3082<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u308a\u307e\u3057\u305f\u3002\u3069\u3053\u306b\u3044\u3066\u3082<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3092\u3068\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3057\u3001\u308f\u304b\u3089\u306a\u3044\u3053\u3068\u306f\u3044\u3064\u3067\u3082<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002</u>(A)</p>\n        <p>\u3057\u304b\u3057\u3001<u><ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u307e\u3067\u3088\u304f<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u308f\u308c\u3066\u3044\u305f\u3082\u306e\u304c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u305f\u3061\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u304b\u3089\u306a\u304f\u306a\u308a\u307e\u3057\u305f\u3002<ruby>\u8857<rt>\u307e\u3061</rt></ruby><ruby>\u4e2d<rt>\u3058\u3085\u3046</rt></ruby>\u304b\u3089<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u30dc\u30c3\u30af\u30b9\u304c<ruby>\u6d88<rt>\u304d</rt></ruby>\u3048\u3001<ruby>\u7d19<rt>\u304b\u307f</rt></ruby>\u306e<ruby>\u8f9e<rt>\u3058</rt></ruby><ruby>\u66f8<rt>\u3057\u3087</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3063\u3066<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3059\u308b<ruby>\u5b66<rt>\u304c\u304f</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u3082\u307b\u3068\u3093\u3069\u3044\u306a\u304f\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u306e\u3067\u3059\u3002</u>(B)</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p><u>Dengan hadirnya ponsel pintar, kehidupan masyarakat menjadi sangat praktis. Di mana pun berada kita dapat menghubungi teman, dan hal yang tidak diketahui dapat dicari kapan saja.</u> (A)</p>\n        <p>Akan tetapi, <u>benda-benda yang dulunya sering digunakan kini menghilang dari kehidupan kita. Boks telepon umum lenyap dari seluruh penjuru kota, dan pelajar yang belajar menggunakan kamus kertas pun hampir tidak ada lagi.</u> (B)</p>\n      </div>\n    </div>\n\n    <!-- Hubungan 3: Sebab-Akibat -->\n    <div class=\"info-box\">\n      <h4>3. Hubungan Sebab-Akibat (<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u30fb<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3000A\u2192B)</h4>\n      <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh Dasar):</strong></p>\n      <p>\n        <u><ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u6bce<rt>\u307e\u3044</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby><ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3059</u>\u3002(A)<br>\n        \u3060\u304b\u3089\u3001<u><ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u3059</u>\u3002(B)<br>\n        <em><u>Saya belajar bahasa Jepang setiap hari</u>. (A) Oleh karena itu, <u>saya mahir berbahasa Jepang</u>. (B)</em>\n      </p>\n      <p>\n        <ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u6bce<rt>\u307e\u3044</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby><ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3059\u3002(A) [<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby> / Alasan] \u2192 <ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u3059\u3002(B) [<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby> / Akibat]<br>\n        \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067\u3001\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u6bce<rt>\u307e\u3044</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby><ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u3066\u3044\u307e\u3059\u3002\u300d\u3068\u300c<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u3059\u3002\u300d\u306f\u3001<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u30fb<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u3067\u3059\u3002<br>\n        <em>Dalam bacaan ini, \"Saya belajar bahasa Jepang setiap hari.\" dan \"Saya mahir berbahasa Jepang.\" memiliki hubungan sebab-akibat.</em>\n      </p>\n\n      <p><strong>\u2460 <ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2192B (Mencari Kata dalam Hubungan Sebab-Akibat)</strong></p>\n      <p>\n        \u203b<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3060\u3051\u3067\u306f\u300c<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u30fb<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby><ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u300d\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3092<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u308b\u3053\u3068\u306f\u3067\u304d\u307e\u305b\u3093\u3002<br>\n        <em>Catatan: Hanya dari satu kata saja, soal \"hubungan sebab-akibat\" tidak dapat dibuat.</em>\n      </p>\n\n      <p><strong>\u2461 <ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2192B (Mencari Kalimat dalam Hubungan Sebab-Akibat)</strong></p>\n      <div class=\"reading-passage\">\n        <p>2010<ruby>\u5e74<rt>\u306d\u3093</rt></ruby>\u3054\u308d\u304b\u3089\u3001<u>\u30b9\u30de\u30db\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby><ruby>\u4e2d<rt>\u3058\u3085\u3046</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u308a\u3001\u305d\u308c\u3068<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b<ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f\u306e\u30a2\u30d7\u30ea\u304c<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u3089\u308c\u307e\u3057\u305f</u>(A)\u3002\u305d\u306e\u305f\u3081<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3092<ruby>\u53d6<rt>\u3068</rt></ruby>\u308a<ruby>\u5408<rt>\u3042</rt></ruby>\u3046\u3053\u3068\u3001\u304a\u3082\u3057\u308d\u3044<ruby>\u6620<rt>\u3048\u3044</rt></ruby><ruby>\u753b<rt>\u304c</rt></ruby>\u3092\u307f\u308b\u3053\u3068\u3001\u30b3\u30f3\u30d3\u30cb\u3067\u304a<ruby>\u91d1<rt>\u304b\u306d</rt></ruby>\u3092<ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046\u3053\u3068\u3001<u>\u3044\u308d\u3093\u306a\u3053\u3068\u304c\u30b9\u30de\u30db<ruby>\u4e00<rt>\u3072\u3068</rt></ruby>\u3064\u3067\u3067\u304d\u308b\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f</u>(B)\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Sejak sekitar tahun 2010, <u>ponsel pintar menyebar ke seluruh dunia dan pada saat yang sama banyak aplikasi diciptakan</u> (A). Oleh karena itu, saling menghubungi teman, menonton film yang menarik, membayar di minimarket, <u>berbagai macam hal dapat dilakukan hanya dengan satu ponsel pintar</u> (B).</p>\n      </div>\n\n      <p><strong>\u2462 <ruby>\u6bb5<rt>\u3060\u3093</rt></ruby><ruby>\u843d<rt>\u3089\u304f</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3000A\u2192B (Mencari Paragraf dalam Hubungan Sebab-Akibat)</strong></p>\n      <div class=\"reading-passage\">\n        <p><u>1990<ruby>\u5e74<rt>\u306d\u3093</rt></ruby>\u3054\u308d\u304b\u3089\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c\u3069\u3093\u3069\u3093<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u308a\u307e\u3057\u305f\u3002<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b\u3001\u30d1\u30bd\u30b3\u30f3\u3084\u30b9\u30de\u30db\u306a\u3069\u306e<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u6570<rt>\u304b\u305a</rt></ruby><ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u3089\u308c\u3066\u304d\u307e\u3057\u305f\u3002</u>(A)</p>\n        <p>\u305d\u308c\u306b\u3088\u3063\u3066\u3001<u><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby>\u306b<ruby>\u884c<rt>\u3044</rt></ruby>\u304b\u305a\u306b<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u3067<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u307e\u3057\u305f\u3002\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8<ruby>\u4e0a<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3042\u308b<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3063\u3066\u3001\u30d3\u30c7\u30aa<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3067<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c\u3001<ruby>\u5f53<rt>\u3042</rt></ruby>\u305f\u308a<ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b\u306a\u3063\u3066\u304d\u3066\u3044\u307e\u3059\u3002</u>(B)</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p><u>Sejak sekitar tahun 1990, internet menyebar dengan pesat ke seluruh dunia. Pada saat yang sama, banyak perangkat baru seperti komputer dan ponsel pintar pun diciptakan.</u> (A)</p>\n        <p>Akibatnya, <u>lahirlah cara kerja baru, yaitu bekerja di rumah tanpa pergi ke kantor. Cara kerja mengadakan rapat melalui panggilan video dengan menggunakan dokumen yang ada di internet kini mulai menjadi hal yang biasa.</u> (B)</p>\n      </div>\n    </div>\n\n    <!-- Langkah 3: Mencari 3 Pilihan yang Salah -->\n    <div class=\"info-box\">\n      <h4>Langkah 3. Mencari 3 Pilihan Jawaban yang Salah (3. 3\u3064\u306e<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059)</h4>\n      <p>\n        <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u306b<ruby>\u5bfe<rt>\u305f\u3044</rt></ruby>\u3059\u308b<ruby>\u6b63<rt>\u305f\u3060</rt></ruby>\u3057\u3044<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u306e\u3067\u306f\u306a\u304f\u30013\u3064\u306e<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u3068<ruby>\u6bd4<rt>\u304f\u3089</rt></ruby>\u3079\u306a\u304c\u3089<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059\u3053\u3068\u304c<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3067\u3059\u3002<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u306b\u306f\u3053\u306e\u3088\u3046\u306a\u3082\u306e\u304c\u3042\u308a\u307e\u3059\u3002<br>\n        <em>Alih-alih langsung mencari pilihan yang benar atas pertanyaan, hal yang penting adalah mencari 3 pilihan yang salah sambil membandingkannya dengan isi teks. Pilihan yang salah memiliki pola seperti berikut ini:</em>\n      </p>\n\n      <p><strong>Pola 1: Tidak disebutkan di dalam teks (<ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3067<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044)</strong></p>\n      <p>\n        <strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh):</strong><br>\n        <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff1a<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f\u3001\u3086\u304b<ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u306b<ruby>\u4f1a<rt>\u3042</rt></ruby>\u3063\u3066<u><ruby>\u8a71<rt>\u306f\u306a</rt></ruby>\u3057\u305f\u3044</u>\u3067\u3059\u3002<br>\n        <em>Teks: Saya ingin bertemu Bu Guru Yuka dan <u>berbicara dengannya</u>.</em><br>\n        <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\uff1a\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u3092\u3057\u305f\u3044\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u307e\u3059\u304b\u3002<br>\n        <em>Pertanyaan: Penulis teks ini mengatakan ingin melakukan apa?</em><br>\n        <ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\uff1a\u3086\u304b<ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u306b<ruby>\u4f1a<rt>\u3042</rt></ruby>\u3063\u3066<u>\u3046\u3069\u3093\u3092<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f\u3044</u>\u3067\u3059\u3002\u00d7<br>\n        <em>Pilihan: Ingin bertemu Bu Guru Yuka dan <u>makan udon</u>. \u00d7</em><br>\n        \u203b <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3067\u306f<u>\u3046\u3069\u3093\u3092<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f\u3044</u>\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044<br>\n        <em>\u203b Di dalam teks tidak dikatakan <u>ingin makan udon</u>.</em>\n      </p>\n\n      <p><strong>Pola 2: Hal yang dikatakan dalam teks dihilangkan pada pilihan (<ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3067<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u308b\u3053\u3068\u304c\u3001<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3067<ruby>\u629c<rt>\u306c</rt></ruby>\u3051\u3066\u3044\u308b)</strong></p>\n      <p>\n        <strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh):</strong><br>\n        <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff1a<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f\u3001\u3086\u304b<ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u306b<u><ruby>\u4f1a<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u3063\u3057\u3087\u306b<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3092\u3057\u305f\u3044</u>\u3067\u3059\u3002<br>\n        <em>Teks: Saya ingin <u>bertemu Bu Guru Yuka dan makan bersama</u>.</em><br>\n        <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\uff1a\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u3092\u3057\u305f\u3044\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u307e\u3059\u304b\u3002<br>\n        <em>Pertanyaan: Penulis teks ini mengatakan ingin melakukan apa?</em><br>\n        <ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\uff1a\u3086\u304b<ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u306b<u><ruby>\u4f1a<rt>\u3042</rt></ruby>\u3044\u305f\u3044</u>\u3067\u3059\u3002\u00d7<br>\n        <em>Pilihan: Ingin <u>bertemu</u> Bu Guru Yuka. \u00d7</em><br>\n        \u203b <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3067\u306f<u>\u3044\u3063\u3057\u3087\u306b<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3092\u3057\u305f\u3044</u>\u304c<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u306a<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><br>\n        <em>\u203b Di dalam teks, <u>ingin makan bersama</u> merupakan inti informasi yang penting (bagian ini dihilangkan dalam pilihan).</em>\n      </p>\n\n      <p><strong>Pola 3: Kesalahan Pengulangan (<ruby>\u7e70<rt>\u304f</rt></ruby>\u308a<ruby>\u8fd4<rt>\u304b\u3048</rt></ruby>\u3057\u3066\u3044\u308b<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044)</strong></p>\n      <p>\n        \u300cA\u3060\u304b\u3089B\u300d\u306a\u306e\u306b\u3001\u300cB\u3060\u304b\u3089B\u300d\u3068\u3044\u3046<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044<br>\n        <em>Kesalahan ketika hubungan sebenarnya adalah \"karena A, maka B\", namun pada pilihan dijawab \"karena B, maka B\".</em>\n      </p>\n      <p>\n        <strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby> (Contoh):</strong><br>\n        <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff1a<u>\u3061\u3083\u3093\u3068<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3092\u3057\u306a\u304b\u3063\u305f</u>(A)\u305b\u3044\u3067\u3001<u>\u30c6\u30b9\u30c8\u30670<ruby>\u70b9<rt>\u3066\u3093</rt></ruby>\u3092\u3068\u308a\u307e\u3057\u305f</u>(B)\u3002<u>\u30c6\u30b9\u30c8\u3067<ruby>\u60aa<rt>\u308f\u308b</rt></ruby>\u3044<ruby>\u70b9<rt>\u3066\u3093</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u3092\u3068\u3063\u305f\u306e\u3067</u>(B)<u><ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby>\u306b<ruby>\u6012<rt>\u304a\u3053</rt></ruby>\u3089\u308c\u307e\u3057\u305f</u>(C)\u3002<br>\n        <em>Teks: Gara-gara <u>tidak belajar dengan sungguh-sungguh</u> (A), saya <u>mendapat nilai 0 dalam ujian</u> (B). Karena <u>mendapat nilai jelek dalam ujian</u> (B), saya <u>dimarahi oleh guru</u> (C).</em><br>\n        <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\uff1a<u>\u30c6\u30b9\u30c8\u30670<ruby>\u70b9<rt>\u3066\u3093</rt></ruby>\u3092\u3068\u3063\u305f</u>(B)\u306e\u306f\u3069\u3046\u3057\u3066\u3067\u3059\u304b\u3002<br>\n        <em>Pertanyaan: Mengapa ia <u>mendapat nilai 0 dalam ujian</u> (B)?</em><br>\n        <ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\uff1a<br>\n        \u30fb<u>\u30c6\u30b9\u30c8\u3067<ruby>\u60aa<rt>\u308f\u308b</rt></ruby>\u3044<ruby>\u70b9<rt>\u3066\u3093</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u3092\u3068\u3063\u305f</u>(B)\u304b\u3089\u3067\u3059\u3002\u00d7 <em>(Karena <u>mendapat nilai jelek dalam ujian</u> [B]. \u00d7)</em><br>\n        \u30fb<u>\u3061\u3083\u3093\u3068<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3092\u3057\u306a\u304b\u3063\u305f</u>(A)\u304b\u3089\u3067\u3059\u3002\u3007 <em>(Karena <u>tidak belajar dengan sungguh-sungguh</u> [A]. \u3007)</em><br>\n        <u>\u30c6\u30b9\u30c8\u3067<ruby>\u60aa<rt>\u308f\u308b</rt></ruby>\u3044<ruby>\u70b9<rt>\u3066\u3093</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u3092\u3068\u3063\u305f</u>(B)\u304b\u3089<u>\u30c6\u30b9\u30c8\u30670<ruby>\u70b9<rt>\u3066\u3093</rt></ruby>\u3092\u3068\u3063\u305f</u>(B)\u306f\u3001<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby>\u306e\u3053\u3068\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u306e\u3088\u3046\u306b<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u308b\u3002\u3053\u308c\u306f<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u3002<br>\n        <em>Mengatakan \"mendapat nilai 0 dalam ujian\" (B) karena \"mendapat nilai jelek dalam ujian\" (B) adalah menyebut hal yang memiliki makna/hubungan sama seolah-olah menjadi alasannya. Ini adalah kesalahan.</em>\n      </p>\n    </div>\n\n    <!-- Langkah 4: Contoh Cara Mengerjakan -->\n    <div class=\"info-box\">\n      <h4>Langkah 4. Contoh Cara Mengerjakan Soal (4. <ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306e<ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>)</h4>\n      <p>Berikut adalah 3 contoh soal beserta langkah-langkah penyelesaiannya secara langsung berdasarkan ketiga langkah di atas.</p>\n    </div>\n\n    <!-- Contoh 1 -->\n    <div class=\"practice-item\" id=\"example-1\">\n      <h5><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>1 (Contoh 1)</h5>\n      <div class=\"reading-passage\">\n        <p><ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a\u3053\u3068\u3092<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u308f\u308c\u3066\u3044\u307e\u3059\u3002<ruby>\u76ee<rt>\u3081</rt></ruby>\u3060\u3051\u3067\u306a\u304f\u3001<ruby>\u53e3<rt>\u304f\u3061</rt></ruby>\u3084<ruby>\u8033<rt>\u307f\u307f</rt></ruby>\u306a\u3069\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3082<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3068\u3001<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u306e\u3067\u3059\u3002<ruby>\u4f8b<rt>\u305f\u3068</rt></ruby>\u3048\u3070\u3001<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u3060\u3051\u3067\u306a\u304f\u3001<ruby>\u58f0<rt>\u3053\u3048</rt></ruby>\u306b<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u306a\u304c\u3089<ruby>\u66f8<rt>\u304b</rt></ruby>\u304f\u306a\u3069<ruby>\u8907<rt>\u3075\u304f</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3068\u3001<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u3084\u3059\u304f\u306a\u308b\u3088\u3046\u3067\u3059\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Dikatakan bahwa manusia dapat mengingat berbagai hal dengan cepat apabila menggunakan banyak indra sekaligus. Tidak hanya mata, jika kita juga menggunakan indra seperti mulut dan telinga secara bersamaan, kita dapat mengingat dengan cepat. Misalnya, tidak hanya membaca, jika kita menggunakan beberapa indra bersama-sama seperti menulis sambil melafalkannya dengan suara, tampaknya hal tersebut menjadi lebih mudah diingat.</p>\n      </div>\n\n      <div class=\"question-block\">\n        <p class=\"question-text\">\n          \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f\u3001\u3069\u306e\u3088\u3046\u306b<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u308b\u304b\u3002<br>\n          <em>Bagaimanakah pendapat penulis teks ini?</em>\n        </p>\n        <ol class=\"options-list\">\n          <li><ruby>\u5fc3<rt>\u3053\u3053\u308d</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u3068<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002<br><em>Jika membaca dalam hati, dapat mengingat dengan cepat.</em></li>\n          <li><ruby>\u58f0<rt>\u3053\u3048</rt></ruby>\u306b<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u306a\u304c\u3089\u3001\u304d\u308c\u3044\u306b\u30ce\u30fc\u30c8\u306b\u307e\u3068\u3081\u308b\u3068\u3044\u3044\u3002<br><em>Sebaiknya merangkum dengan rapi di buku catatan sambil melafalkannya dengan suara.</em></li>\n          <li><ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b<ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u3089\u308c\u308b\u3002<br><em>Dengan menggunakan banyak indra sekaligus, kita dapat mengingat dengan cepat.</em></li>\n          <li><ruby>\u4f55<rt>\u306a\u3093</rt></ruby><ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u3068\u3057\u3063\u304b\u308a<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002<br><em>Jika membaca berkali-kali, dapat mengingat dengan mantap.</em></li>\n        </ol>\n      </div>\n\n      <div class=\"answer-box\">\n        <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>1\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306e<ruby>\u9806<rt>\u3058\u3085\u3093</rt></ruby>\u3000<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby> (Urutan &amp; Cara Praktis Mengerjakan Contoh 1)</strong></p>\n        <p>\n          <strong>\u2460 <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080 (Membaca kalimat pertanyaan):</strong><br>\n          \u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304c<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3055\u308c\u3066\u3044\u308b\u304b\u3092<ruby>\u982d<rt>\u3042\u305f\u307e</rt></ruby>\u306b<ruby>\u5165<rt>\u3044</rt></ruby>\u308c\u307e\u3059\u3002<br>\n          \uff08\u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u306f\u3001\u300c\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f\u3069\u306e\u3088\u3046\u306b<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u308b\u304b\u3002\u300d\uff09<br>\n          <em>Pahami apa yang ditanyakan dalam soal ini (Di sini pertanyaannya: \"Bagaimanakah pendapat penulis teks ini?\").</em>\n        </p>\n        <p>\n          <strong>\u2461 <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3001<ruby>\u6d41<rt>\u306a\u304c</rt></ruby>\u308c\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3059\u308b (Membaca teks dan memahami alurnya):</strong><br>\n          \u30fb<u><ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306f<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a\u3053\u3068\u3092<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b</u>\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u308f\u308c\u3066\u3044\u307e\u3059\u3002<br>\n          \u3000\u2192 <em>(<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a\u3053\u3068\u3092<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b)</em><br>\n          \u30fb<u><ruby>\u76ee<rt>\u3081</rt></ruby>\u3060\u3051\u3067\u306a\u304f\u3001<ruby>\u53e3<rt>\u304f\u3061</rt></ruby>\u3084<ruby>\u8033<rt>\u307f\u307f</rt></ruby>\u306a\u3069\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3082<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3068\u3001<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u306e\u3067\u3059\u3002</u><br>\n          \u3000\u2192 <em>(<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a\u3053\u3068\u3092<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\uff1a<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby> / Hubungan sama)</em><br>\n          \u30fb<ruby>\u4f8b<rt>\u305f\u3068</rt></ruby>\u3048\u3070\u3001<u><ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u3060\u3051\u3067\u306a\u304f\u3001<ruby>\u58f0<rt>\u3053\u3048</rt></ruby>\u306b<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u306a\u304c\u3089<ruby>\u66f8<rt>\u304b</rt></ruby>\u304f\u306a\u3069<ruby>\u8907<rt>\u3075\u304f</rt></ruby><ruby>\u6570<rt>\u3059\u3046</rt></ruby>\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3068\u3001<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u3084\u3059\u304f\u306a\u308b</u>\u3088\u3046\u3067\u3059\u3002<br>\n          \u3000\u2192 <em>(<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a\u3053\u3068\u3092<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\uff1a<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby> / Hubungan sama)</em><br>\n          <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092\u307e\u3068\u3081\u308b\u3068\u300c\u305f\u304f\u3055\u3093\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067\u3001<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u300d\u3067\u3059\u3002<br>\n          <em>Jika diringkas, isi bacaan adalah \"Dengan menggunakan banyak indra, kita dapat mengingat dengan cepat.\"</em>\n        </p>\n        <p><strong>\u2462 3\u3064\u306e<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059 (Mencari 3 pilihan yang salah):</strong></p>\n        <ul>\n          <li>1\u3000<u><ruby>\u5fc3<rt>\u3053\u3053\u308d</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080</u>\u3068<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u5fc3<rt>\u3053\u3053\u308d</rt></ruby>\u306e<ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3067<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Tidak disebutkan \"membaca dalam hati\".</em></li>\n          <li>2\u3000<ruby>\u58f0<rt>\u3053\u3048</rt></ruby>\u306b<ruby>\u51fa<rt>\u3060</rt></ruby>\u3057\u306a\u304c\u3089\u3001<u>\u304d\u308c\u3044\u306b\u30ce\u30fc\u30c8\u306b\u307e\u3068\u3081\u308b</u>\u3068\u3044\u3044\u3002\uff08\u00d7\uff09<br>\u300c\u304d\u308c\u3044\u306b\u30ce\u30fc\u30c8\u306b\u307e\u3068\u3081\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Tidak disebutkan \"merangkum dengan rapi di buku catatan\".</em></li>\n          <li><strong>3\u3000<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u306b<ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f\u306e<ruby>\u611f<rt>\u304b\u3093</rt></ruby><ruby>\u899a<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3046\u3053\u3068\u3067<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u3089\u308c\u308b\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar!</em></li>\n          <li>4\u3000<u><ruby>\u4f55<rt>\u306a\u3093</rt></ruby><ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080</u>\u3068\u3057\u3063\u304b\u308a<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u4f55<rt>\u306a\u3093</rt></ruby><ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Tidak disebutkan \"membaca berkali-kali\".</em></li>\n        </ul>\n      </div>\n    </div>\n\n    <!-- Contoh 2 -->\n    <div class=\"practice-item\" id=\"example-2\">\n      <h5><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>2 (Contoh 2)</h5>\n      <div class=\"reading-passage\">\n        <p>1990<ruby>\u5e74<rt>\u306d\u3093</rt></ruby>\u3054\u308d\u304b\u3089\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c\u3069\u3093\u3069\u3093<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u308a\u307e\u3057\u305f\u3002<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b\u3001\u30d1\u30bd\u30b3\u30f3\u3084\u30b9\u30de\u30db\u306a\u3069\u306e<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u6570<rt>\u304b\u305a</rt></ruby><ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u3089\u308c\u3066\u304d\u307e\u3057\u305f\u3002</p>\n        <p>\u305d\u308c\u306b\u3088\u3063\u3066\u3001<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby>\u306b<ruby>\u884c<rt>\u3044</rt></ruby>\u304b\u305a\u306b<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u3067<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u307e\u3057\u305f\u3002\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8<ruby>\u4e0a<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3042\u308b<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3063\u3066\u3001\u30d3\u30c7\u30aa<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3067<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c\u3001<ruby>\u5f53<rt>\u3042</rt></ruby>\u305f\u308a<ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b\u306a\u3063\u3066\u304d\u3066\u3044\u307e\u3059\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Sejak sekitar tahun 1990, internet menyebar dengan pesat ke seluruh dunia. Pada saat yang sama, banyak perangkat baru seperti komputer dan ponsel pintar pun diciptakan.</p>\n        <p>Akibatnya, lahirlah cara kerja baru, yaitu bekerja di rumah tanpa pergi ke kantor. Cara kerja mengadakan rapat melalui panggilan video dengan menggunakan dokumen yang ada di internet kini mulai menjadi hal yang biasa.</p>\n      </div>\n\n      <div class=\"question-block\">\n        <p class=\"question-text\">\n          \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u3068<ruby>\u5408<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002<br>\n          <em>Manakah pernyataan yang sesuai dengan isi teks ini?</em>\n        </p>\n        <ol class=\"options-list\">\n          <li><ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3002<br><em>Karena lahirnya cara kerja baru, internet menyebar ke seluruh dunia.</em></li>\n          <li>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3084<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u3063\u305f\u3002<br><em>Karena internet dan perangkat baru menyebar ke seluruh dunia, kehidupan masyarakat menjadi praktis.</em></li>\n          <li>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3084<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3002<br><em>Karena internet dan perangkat baru menyebar ke seluruh dunia, lahirlah cara kerja baru.</em></li>\n          <li>\u30d3\u30c7\u30aa<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u306e<ruby>\u6d41<rt>\u308a\u3085\u3046</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby>\u306b\u3088\u308a\u3001<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u3067<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3002<br><em>Akibat tren rapat video, lahirlah cara kerja baru yaitu bekerja di rumah.</em></li>\n        </ol>\n      </div>\n\n      <div class=\"answer-box\">\n        <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>2\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306e<ruby>\u9806<rt>\u3058\u3085\u3093</rt></ruby>\u3000<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby> (Urutan &amp; Cara Praktis Mengerjakan Contoh 2)</strong></p>\n        <p>\n          <strong>\u2460 <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080 (Membaca kalimat pertanyaan):</strong><br>\n          \u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304c<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3055\u308c\u3066\u3044\u308b\u304b\u3092<ruby>\u982d<rt>\u3042\u305f\u307e</rt></ruby>\u306b<ruby>\u5165<rt>\u3044</rt></ruby>\u308c\u307e\u3059\u3002<br>\n          \uff08\u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u306f\u3001\u300c\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u3068<ruby>\u5408<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002\u300d\uff09<br>\n          <em>Pahami apa yang ditanyakan (Di sini: \"Manakah pernyataan yang sesuai dengan isi teks ini?\").</em>\n        </p>\n        <p>\n          <strong>\u2461 <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3001<ruby>\u6d41<rt>\u306a\u304c</rt></ruby>\u308c\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3059\u308b (Membaca teks dan memahami alurnya):</strong><br>\n          \u30fb<u>1990<ruby>\u5e74<rt>\u306d\u3093</rt></ruby>\u3054\u308d\u304b\u3089\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c\u3069\u3093\u3069\u3093<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u308a\u307e\u3057\u305f</u>\u3002<em>\uff08<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby> / Alasan\uff09</em><br>\n          \u30fb<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b\u3001\u30d1\u30bd\u30b3\u30f3\u3084\u30b9\u30de\u30db\u306a\u3069\u306e<u><ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u6570<rt>\u304b\u305a</rt></ruby><ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u3089\u308c\u3066\u304d\u307e\u3057\u305f</u>\u3002<em>\uff08<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby> / Alasan\uff09</em><br>\n          \u30fb\u305d\u308c\u306b\u3088\u3063\u3066\u3001<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby>\u306b<ruby>\u884c<rt>\u3044</rt></ruby>\u304b\u305a\u306b<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u3067<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<u><ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u307e\u3057\u305f</u>\u3002<em>\uff08<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby> / Akibat\uff09</em><br>\n          \u30fb<u>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8<ruby>\u4e0a<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3042\u308b<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3063\u3066\u3001\u30d3\u30c7\u30aa<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3067<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c</u>\u3001<ruby>\u5f53<rt>\u3042</rt></ruby>\u305f\u308a<ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b\u306a\u3063\u3066\u304d\u3066\u3044\u307e\u3059\u3002<em>\uff08<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u307e\u3057\u305f\uff1a<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u95a2<rt>\u304b\u3093</rt></ruby><ruby>\u4fc2<rt>\u3051\u3044</rt></ruby> / Hubungan sama\uff09</em><br>\n          <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092\u307e\u3068\u3081\u308b\u3068\u3001\u300c\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c\u3069\u3093\u3069\u3093<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3053\u3068\u300d\u3068\u300c<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u3082<ruby>\u6570<rt>\u304b\u305a</rt></ruby><ruby>\u591a<rt>\u304a\u304a</rt></ruby>\u304f<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u3089\u308c\u3066\u304d\u305f\u300d\u306b\u3088\u3063\u3066\u3001\u300c<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u307e\u3057\u305f\u3002\u300d\u3067\u3059\u3002<br>\n          <em>Ringkasan teks: Akibat \"internet menyebar pesat ke seluruh dunia\" dan \"banyak perangkat baru diciptakan\", maka \"lahirlah cara kerja baru\".</em>\n        </p>\n        <p><strong>\u2462 3\u3064\u306e<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059 (Mencari 3 pilihan yang salah):</strong></p>\n        <ul>\n          <li>1\u3000<u><ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f</u>\u3002\uff08\u00d7\uff09<br><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3068<ruby>\u7d50<rt>\u3051\u3063</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby>\u304c<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby>: <em>Sebab dan akibatnya terbalik.</em></li>\n          <li>2\u3000\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3084<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<u><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u3063\u305f</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u306f<ruby>\u4fbf<rt>\u3079\u3093</rt></ruby><ruby>\u5229<rt>\u308a</rt></ruby>\u306b\u306a\u3063\u305f\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"kehidupan menjadi praktis\".</em></li>\n          <li><strong>3\u3000\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3084<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u6a5f<rt>\u304d</rt></ruby><ruby>\u68b0<rt>\u304b\u3044</rt></ruby>\u304c<ruby>\u4e16<rt>\u305b</rt></ruby><ruby>\u754c<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u5e83<rt>\u3072\u308d</rt></ruby>\u307e\u3063\u305f\u3053\u3068\u306b\u3088\u3063\u3066\u3001<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar!</em></li>\n          <li>4\u3000<u>\u30d3\u30c7\u30aa<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u306e<ruby>\u6d41<rt>\u308a\u3085\u3046</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby></u>\u306b\u3088\u308a\u3001<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u3067<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u3092\u3059\u308b\u3068\u3044\u3046<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u50cd<rt>\u306f\u305f\u3089</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u751f<rt>\u3046</rt></ruby>\u307e\u308c\u305f\u3002\uff08\u00d7\uff09<br><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3068\u3057\u3066\u300c\u30d3\u30c7\u30aa<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby>\u306e<ruby>\u6d41<rt>\u308a\u3085\u3046</rt></ruby><ruby>\u884c<rt>\u3053\u3046</rt></ruby>\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Tidak disebutkan \"tren rapat video\" sebagai alasannya.</em></li>\n        </ul>\n      </div>\n    </div>\n\n    <!-- Contoh 3 -->\n    <div class=\"practice-item\" id=\"example-3\">\n      <h5><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>3 (Contoh 3)</h5>\n      <div class=\"reading-passage\">\n        <p><ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306f<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby>\u304b\u3089<ruby>\u4e00\u4eba<rt>\u3072\u3068\u308a</rt></ruby><ruby>\u66ae<rt>\u3050</rt></ruby>\u3089\u3057\u3092<ruby>\u59cb<rt>\u306f\u3058</rt></ruby>\u3081\u307e\u3057\u305f\u3002<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3084\u30a2\u30eb\u30d0\u30a4\u30c8\u3082\u3046\u307e\u304f\u3044\u3063\u3066\u3001<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3082<ruby>\u5897<rt>\u3075</rt></ruby>\u3048\u3066\u3001<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3044<ruby>\u5b66<rt>\u304c\u304f</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u3092<ruby>\u9001<rt>\u304a\u304f</rt></ruby>\u3063\u3066\u3044\u307e\u3057\u305f\u304c\u3001<ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u306f<ruby>\u82e6<rt>\u306b\u304c</rt></ruby><ruby>\u624b<rt>\u3066</rt></ruby>\u3060\u3063\u305f\u306e\u3067\u3001<ruby>\u6bce<rt>\u307e\u3044</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>\u30ab\u30c3\u30d7\u30e9\u30fc\u30e1\u30f3\u3092<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u3066\u3044\u307e\u3057\u305f\u3002\u3059\u308b\u3068\u3001<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby><ruby>\u4e0d<rt>\u3076</rt></ruby><ruby>\u8db3<rt>\u305d\u304f</rt></ruby>\u306e\u305b\u3044\u3067\u30af\u30e9\u30d6<ruby>\u6d3b<rt>\u304b\u3064</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby><ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby>\u306b<ruby>\u5012<rt>\u305f\u304a</rt></ruby>\u308c\u3066\u3057\u307e\u3044\u3001\u3057\u3070\u3089\u304f<ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u9662<rt>\u3044\u3093</rt></ruby>\u3059\u308b\u3053\u3068\u306b\u306a\u308a\u307e\u3057\u305f\u3002<ruby>\u5143<rt>\u3052\u3093</rt></ruby><ruby>\u6c17<rt>\u304d</rt></ruby>\u306b<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby>\u3059\u308b\u305f\u3081\u306b\u306f<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u304c<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u756a<rt>\u3070\u3093</rt></ruby><ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3060\u3068\u3044\u3046\u3053\u3068\u3092<ruby>\u5b66<rt>\u307e\u306a</rt></ruby>\u3073\u3001\u305d\u308c\u304b\u3089\u306f<ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3067<ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u3092<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u308b\u3088\u3046\u306b\u306a\u308a\u3001<ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u6642<rt>\u3058</rt></ruby>\u306b<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002<ruby>\u6bce<rt>\u307e\u3044</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby><ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3067\u30e1\u30cb\u30e5\u30fc\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u308b\u3068\u3001\u3082\u3063\u3068<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u306e<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3092\u3057\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3046\u3088\u3046\u306b\u306a\u308a\u307e\u3057\u305f\u3002</p>\n        <p><ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u306f<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby>\u3092\u3084\u3081\u3066<ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u306e<ruby>\u5c02<rt>\u305b\u3093</rt></ruby><ruby>\u9580<rt>\u3082\u3093</rt></ruby><ruby>\u5b66<rt>\u304c\u3063</rt></ruby><ruby>\u6821<rt>\u3053\u3046</rt></ruby>\u306b<ruby>\u901a<rt>\u304b\u3088</rt></ruby>\u3063\u3066\u3044\u307e\u3059\u3002<ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u306f\u30ec\u30b9\u30c8\u30e9\u30f3\u3092<ruby>\u958b<rt>\u3072\u3089</rt></ruby>\u3044\u3066\u3001<ruby>\u4eba<rt>\u3072\u3068</rt></ruby><ruby>\u3005<rt>\u3073\u3068</rt></ruby>\u306e<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306e<ruby>\u5f79<rt>\u3084\u304f</rt></ruby>\u306b<ruby>\u7acb<rt>\u305f</rt></ruby>\u3061\u305f\u3044\u3067\u3059\u3002</p>\n      </div>\n      <div class=\"passage-trans-box\">\n        <h4>Terjemahan Teks:</h4>\n        <p>Saya mulai tinggal sendiri sejak masuk universitas. Kuliah maupun kerja paruh waktu berjalan lancar, teman-teman pun bertambah, dan saya menjalani kehidupan mahasiswa yang menyenangkan. Namun, karena tidak pandai memasak, saya makan cup ramen (mi instan gelas) setiap hari. Akibatnya, karena kekurangan gizi, saya pingsan saat kegiatan klub dan harus dirawat di rumah sakit untuk sementara waktu. Saya belajar bahwa kesehatan adalah hal yang paling penting untuk hidup dengan bugar, dan sejak saat itu saya mulai memasak sendiri sekaligus memperhatikan gizi. Ketika mulai memikirkan menu sendiri setiap hari, saya menjadi ingin belajar lebih banyak tentang ilmu gizi.</p>\n        <p>Sekarang saya berhenti dari universitas dan bersekolah di sekolah kejuruan memasak. Di masa depan, saya ingin membuka restoran dan bermanfaat bagi kesehatan orang banyak.</p>\n      </div>\n\n      <div class=\"question-block\">\n        <p class=\"question-text\">\n          \u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u304c<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u306e\u306f\u306a\u305c\u304b\u3002<br>\n          <em>Mengapa penulis teks ini mulai memperhatikan/memikirkan gizi?</em>\n        </p>\n        <ol class=\"options-list\">\n          <li><ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3067\u30e1\u30cb\u30e5\u30fc\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u304b\u3089\u3002<br><em>Karena mulai memikirkan menu sendiri.</em></li>\n          <li>\u3082\u3063\u3068<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u306e<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3092\u3057\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3046\u3088\u3046\u306b\u306a\u3063\u305f\u304b\u3089\u3002<br><em>Karena mulai merasa ingin belajar gizi lebih banyak lagi.</em></li>\n          <li><ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u304c<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u756a<rt>\u3070\u3093</rt></ruby><ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3060\u3068\u3044\u3046\u3053\u3068\u304c\u308f\u304b\u3063\u305f\u304b\u3089\u3002<br><em>Karena menyadari bahwa kesehatan adalah hal yang paling penting.</em></li>\n          <li><ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u30ec\u30b9\u30c8\u30e9\u30f3\u3092<ruby>\u958b<rt>\u3072\u3089</rt></ruby>\u304d\u305f\u3044\u304b\u3089\u3002<br><em>Karena ingin membuka restoran di masa depan.</em></li>\n        </ol>\n      </div>\n\n      <div class=\"answer-box\">\n        <p><strong><ruby>\u4f8b<rt>\u308c\u3044</rt></ruby>3\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306e<ruby>\u9806<rt>\u3058\u3085\u3093</rt></ruby>\u3000<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306e<ruby>\u89e3<rt>\u3068</rt></ruby>\u304d<ruby>\u65b9<rt>\u304b\u305f</rt></ruby> (Urutan &amp; Cara Praktis Mengerjakan Contoh 3)</strong></p>\n        <p>\n          <strong>\u2460 <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u3080 (Membaca kalimat pertanyaan):</strong><br>\n          \u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304c<ruby>\u8cea<rt>\u3057\u3064</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3055\u308c\u3066\u3044\u308b\u304b\u3092<ruby>\u982d<rt>\u3042\u305f\u307e</rt></ruby>\u306b<ruby>\u5165<rt>\u3044</rt></ruby>\u308c\u307e\u3059\u3002<br>\n          \uff08\u3053\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u306f\u3001\u300c\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u304c<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u306e\u306f\u306a\u305c\u304b\u3002\u300d\uff09<br>\n          <em>Pahami apa yang ditanyakan (Di sini: \"Mengapa penulis teks ini mulai memikirkan gizi?\").</em>\n        </p>\n        <p>\n          <strong>\u2461 <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u3001<ruby>\u6d41<rt>\u306a\u304c</rt></ruby>\u308c\u3092<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3059\u308b (Membaca teks dan memahami alurnya):</strong><br>\n          <ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u3092\u307e\u3068\u3081\u308b\u3068\u300c<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby><ruby>\u4e0d<rt>\u3076</rt></ruby><ruby>\u8db3<rt>\u305d\u304f</rt></ruby>\u306b\u3088\u308a<ruby>\u5012<rt>\u305f\u304a</rt></ruby>\u308c\u305f\u3053\u3068\u3067<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306e<ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3055\u304c\u308f\u304b\u308a\u3001<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u306a\u304c\u3089<ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3067<ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u3092\u3059\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u3002\u305d\u3053\u3067<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u306b\u3064\u3044\u3066\u3082\u3063\u3068<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3057\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3046\u3088\u3046\u306b\u306a\u3063\u305f\u3002\u300d\u3067\u3059\u3002<br>\n          <em>Ringkasan teks: \"Karena pingsan akibat kekurangan gizi, ia menyadari pentingnya kesehatan, lalu mulai memasak sendiri sambil memikirkan gizi. Dari situlah ia menjadi ingin belajar lebih banyak tentang gizi.\"</em>\n        </p>\n        <p><strong>\u2462 3\u3064\u306e<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044\u306e<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3059 (Mencari 3 pilihan yang salah):</strong></p>\n        <ul>\n          <li>1\u3000<u><ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3067\u30e1\u30cb\u30e5\u30fc\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u304b\u3089</u>\u3002\uff08\u00d7\uff09<br><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a<ruby>\u8fd4<rt>\u304b\u3048</rt></ruby>\u3057\u3066\u3044\u308b<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3044: <em>Kesalahan pengulangan (hal yang hampir sama dianggap sebagai alasan).</em></li>\n          <li>2\u3000<u>\u3082\u3063\u3068<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u306e<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3092\u3057\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3046\u3088\u3046\u306b\u306a\u3063\u305f\u304b\u3089</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u300d\u3053\u3068\u306e<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3067\u306f\u306a\u3044: <em>Bukan alasan mengapa ia \"mulai memikirkan gizi\" (itu terjadi sesudahnya).</em></li>\n          <li><strong>3\u3000<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u304c<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u756a<rt>\u3070\u3093</rt></ruby><ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3060\u3068\u3044\u3046\u3053\u3068\u304c\u308f\u304b\u3063\u305f\u304b\u3089\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar!</em></li>\n          <li>4\u3000<u><ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u30ec\u30b9\u30c8\u30e9\u30f3\u3092<ruby>\u958b<rt>\u3072\u3089</rt></ruby>\u304d\u305f\u3044\u304b\u3089</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u300d\u3053\u3068\u306e<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3067\u306f\u306a\u3044: <em>Bukan alasan mengapa ia \"mulai memikirkan gizi\".</em></li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- ==================== BAGIAN 2: LATIHAN SOAL ==================== -->\n  <div class=\"sub-section\" id=\"reading-practice\">\n    <h3>2. Latihan Soal (<ruby>\u7df4<rt>\u308c\u3093</rt></ruby><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>)</h3>\n\n    <!-- ===== MASALAH 4: TANBUN ===== -->\n    <div class=\"reading-section\" id=\"reading-tanbun\">\n      <h4>4. Pemahaman Isi \u00b7 Teks Pendek (<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u77ed<rt>\u305f\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09)</h4>\n\n      <div class=\"info-box\">\n        <p>\n          <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>4\u3067\u306f\u3001<ruby>\u77ed<rt>\u305f\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff08200<ruby>\u5b57<rt>\u3058</rt></ruby><ruby>\u7a0b<rt>\u3066\u3044</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\uff09\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u307e\u3059\u3002\u305d\u3057\u3066\u3001\u304a<ruby>\u77e5<rt>\u3057</rt></ruby>\u3089\u305b\u3084\u30e1\u30fc\u30eb\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u3001\u307e\u305f\u306f<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306e<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u306b\u3064\u3044\u3066\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u77ed<rt>\u305f\u3093</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u306f4\u3064\u306e<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c\u3042\u308a\u30011\u3064\u306e<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3054\u3068\u306b1\u3064\u306e<ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<br>\n          <em>Pada Bagian 4 (Mondai 4), Anda akan membaca teks pendek (sekitar 200 huruf). Soal yang keluar menanyakan isi pemberitahuan atau email, maupun pemikiran/pendapat penulis teks. Pemahaman Isi (Teks Pendek) memiliki 4 bacaan utama, dan tiap bacaan memiliki 1 pertanyaan.</em>\n        </p>\n        <p>\n          <strong>\u554f\u984c4</strong>\u3000\u3064\u304e\u306e\uff081\uff09\u304b\u3089\uff084\uff09\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092\u8aad\u3093\u3067\u3001\u8cea\u554f\u306b\u7b54\u3048\u306a\u3055\u3044\u3002\u7b54\u3048\u306f\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br>\n          <em><strong>Soal 4:</strong> Bacalah teks (1) sampai (4) berikut ini, lalu jawablah pertanyaannya. Pilihlah satu jawaban yang paling tepat dari pilihan 1, 2, 3, atau 4.</em>\n        </p>\n      </div>\n\n      <!-- Tanbun (1) -->\n      <div class=\"practice-item\" id=\"tanbun-1\">\n        <h5>\uff081\uff09</h5>\n        <div class=\"reading-passage\">\n          <p>\u79c1\u306f\u82f1\u8a9e\u304c\u3069\u3046\u3057\u3066\u3082\u82e6\u624b\u3060\u3002\u3044\u304f\u3089\u52c9\u5f37\u3057\u3066\u3082\u5358\u8a9e\u306e\u610f\u5473\u3084\u767a\u97f3\u3092\u899a\u3048\u308b\u3053\u3068\u304c\u3067\u304d\u305a\u3001\u5148\u9031\u3082\u5358\u8a9e\u306e\u30c6\u30b9\u30c8\u3067\u60aa\u3044\u70b9\u6570\u3092\u53d6\u3063\u3066\u3057\u307e\u3063\u305f\u3002\u305d\u306e\u4e00\u65b9\u3001\u53cb\u9054\u306e<ruby>\u7530<rt>\u305f</rt></ruby><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3055\u3093\u306f\u7fd2\u3063\u305f\u3070\u304b\u308a\u306e\u5358\u8a9e\u3082\u3059\u3050\u899a\u3048\u3066\u3057\u307e\u3046\u304f\u3089\u3044\u3001\u82f1\u8a9e\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u3002\u300c\u3069\u3046\u3084\u3063\u3066\u3044\u308b\u306e\u3002\u300d\u3068\u8cea\u554f\u3057\u305f\u3089\u3001\u300c\u899a\u3048\u305f\u3044\u5358\u8a9e\u306e\u4f8b\u6587\u3092\u3001<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306b\u4f1a\u8a71\u3057\u3066\u3044\u308b\u3088\u3046\u306a\u611f\u3058\u3067\u8aad\u3093\u3067\u307f\u308b\u3068\u3044\u3044\u3088\u3002\u6587\u5b57\u3092\u898b\u308b\u3060\u3051\u3060\u3068\u3059\u3050\u306b\u5fd8\u308c\u3061\u3083\u3046\u3088\u306d\u3002\u300d\u3068\u7b54\u3048\u3066\u304f\u308c\u305f\u3002\u5f7c\u306e\u8003\u3048\u65b9\u306f\u3068\u3066\u3082\u304a\u3082\u3057\u308d\u3044\u3068\u601d\u3063\u305f\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p>Saya benar-benar tidak pandai bahasa Inggris. Sebanyak apa pun belajar, saya tidak bisa menghafal arti maupun pelafalan kosakata, dan minggu lalu pun saya mendapat nilai jelek dalam ujian kosakata. Sebaliknya, teman saya Sdr. Tanaka sangat mahir bahasa Inggris sampai-sampai kosakata yang baru saja dipelajari pun langsung bisa ia hafal. Ketika saya bertanya, \"Bagaimana caramu melakukannya?\", ia menjawab, \"Cobalah membaca kalimat contoh dari kosakata yang ingin kamu hafal seolah-olah kamu sedang benar-benar bercakap-cakap. Kalau hanya melihat tulisannya saja, pasti cepat lupa, ya.\" Menurut saya, cara berpikirnya sangat menarik.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u300c\u79c1\u300d\u306f<ruby>\u7530<rt>\u305f</rt></ruby><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3055\u3093\u306e\u4f55\u304c\u304a\u3082\u3057\u308d\u3044\u3068\u8a00\u3063\u3066\u3044\u307e\u3059\u304b\u3002<br>\n            <em>Menurut \"saya\", hal apa dari Sdr. Tanaka yang dianggap menarik?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u82f1\u8a9e\u306e\u5358\u8a9e\u306e\u899a\u3048\u65b9<br><em>Cara menghafal kosakata bahasa Inggris</em></li>\n            <li>\u5358\u8a9e\u306e\u610f\u5473\u306e\u8abf\u3079\u65b9<br><em>Cara mencari arti kosakata</em></li>\n            <li>\u82f1\u8a9e\u3067\u4f1a\u8a71\u3059\u308b\u65b9\u6cd5<br><em>Cara bercakap-cakap dalam bahasa Inggris</em></li>\n            <li>\u5358\u8a9e\u30c6\u30b9\u30c8\u306e\u53d7\u3051\u65b9<br><em>Cara mengikuti ujian kosakata</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n          <p><strong>\u8cea\u554f\uff1a</strong>1\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u300d\u306f<ruby>\u7530<rt>\u305f</rt></ruby><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby>\u3055\u3093\u306e<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304c\u304a\u3082\u3057\u308d\u3044\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u307e\u3059\u304b\u3002</p>\n          <ul>\n            <li><strong>1\u3000<ruby>\u82f1<rt>\u3048\u3044</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u306e<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u306e<ruby>\u899a<rt>\u304a\u307c</rt></ruby>\u3048<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\uff08\u3007\uff09</strong>: <em>Cara menghafal kosakata bahasa Inggris. (Benar, karena Tanaka membagikan tips menghafal kosakata dengan membaca kalimat contoh seperti sedang bercakap-cakap.)</em></li>\n            <li>2\u3000<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u306e<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u306e<u><ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079<ruby>\u65b9<rt>\u304b\u305f</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u300d\u306b\u3064\u3044\u3066\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dibahas mengenai \"cara mencari arti\".</em></li>\n            <li>3\u3000<ruby>\u82f1<rt>\u3048\u3044</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3067<u><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3059\u308b<ruby>\u65b9<rt>\u307b\u3046</rt></ruby><ruby>\u6cd5<rt>\u307b\u3046</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u3059\u308b<ruby>\u65b9<rt>\u307b\u3046</rt></ruby><ruby>\u6cd5<rt>\u307b\u3046</rt></ruby>\u300d\u306b\u3064\u3044\u3066\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dibahas mengenai \"cara bercakap-cakap dalam bahasa Inggris\".</em></li>\n            <li>4\u3000<u><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u30c6\u30b9\u30c8\u306e<ruby>\u53d7<rt>\u3046</rt></ruby>\u3051<ruby>\u65b9<rt>\u304b\u305f</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u53d7<rt>\u3046</rt></ruby>\u3051<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u300d\u306b\u3064\u3044\u3066\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dibahas mengenai \"cara mengikuti ujian kosakata\".</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): 1</strong></p>\n        </div>\n      </div>\n\n      <!-- Tanbun (2) -->\n      <div class=\"practice-item\" id=\"tanbun-2\">\n        <h5>\uff082\uff09</h5>\n        <div class=\"reading-passage\">\n          <p>3\u304b\u6708\u524d\u304b\u3089\u3001\u98df\u4e8b\u3059\u308b\u56de\u6570\u3092\u4e00\u65e5\u4e00\u56de\u306b\u3057\u3066\u3044\u308b\u3002\u300c\u4e00\u65e53\u56de\u98df\u3079\u306a\u3044\u3068\u3001\u4f53\u306e\u5177\u5408\u304c\u60aa\u304f\u306a\u308b\u300d\u3068\u5b50\u3069\u3082\u306e\u3053\u308d\u304b\u3089\u8a00\u308f\u308c\u3066\u304d\u305f\u304c\u3001\u305d\u308c\u306f\u4eba\u306b\u3088\u3063\u3066\u9055\u3046\u3068\u601d\u3046\u3002</p>\n          <p>\u4ee5\u524d\u306f\u300c\u4e00\u65e53\u56de\u3057\u3063\u304b\u308a\u3054\u98ef\u3092\u98df\u3079\u308b\u3079\u304d\u300d\u3060\u3068\u8003\u3048\u3066\u3044\u305f\u3002\u3057\u304b\u3057\u3001\u4e00\u65e5\u4e2d\u5ea7\u3063\u3066\u4ed5\u4e8b\u3092\u3057\u3066\u3044\u3066\u3001\u3042\u307e\u308a\u304a\u8179\u304c\u7a7a\u304b\u306a\u3044\u3068\u304d\u304c\u3042\u3063\u305f\u305f\u3081\u3001\u304a\u8179\u304c\u7a7a\u3044\u305f\u3068\u304d\u3060\u3051\u98df\u3079\u308b\u3088\u3046\u306b\u3057\u3066\u307f\u305f\u306e\u3060\u3002\u3059\u308b\u3068\u3001\u81ea\u7136\u306b\u4f53\u91cd\u304c<ruby>\u6e1b<rt>\u3078</rt></ruby>\u3063\u3066\u3001\u4f53\u304c\u8efd\u304f\u306a\u3063\u305f\u3002</p>\n          <p>\u4e00\u56de\u306e\u98df\u4e8b\u3067\u3001\u4e00\u65e5\u306b\u5fc5\u8981\u306a<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092\u3068\u308b\u3053\u3068\u304c\u5fc5\u8981\u3060\u3057\u3001\u7121\u7406\u3092\u3057\u305f\u3089\u672c\u5f53\u306b\u4f53\u306e\u5177\u5408\u304c\u60aa\u304f\u306a\u308b\u306e\u3067\u6ce8\u610f\u304c\u5fc5\u8981\u3060\u3002\u3067\u3082\u3001\u4eca\u306f\u81ea\u5206\u306e\u904b\u52d5\u91cf\u306b\u5408\u3063\u305f\u98df\u4e8b\u304c\u3067\u304d\u3066\u3044\u308b\u306e\u3067\u3001\u3053\u308c\u304b\u3089\u3082\u3053\u306e\u751f\u6d3b\u3092\u7d9a\u3051\u305f\u3044\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p>Sejak 3 bulan yang lalu, saya menjadikan frekuensi makan menjadi satu kali sehari. Sejak kecil memang sering dikatakan bahwa \"kalau tidak makan 3 kali sehari, kondisi tubuh akan menjadi buruk\", tetapi menurut saya hal itu berbeda-beda tergantung orangnya.</p>\n          <p>Sebelumnya, saya juga berpikir bahwa \"sebaiknya makan dengan teratur 3 kali sehari\". Akan tetapi, karena saya bekerja sambil duduk seharian dan ada kalanya tidak terlalu merasa lapar, saya mencoba untuk makan hanya saat perut lapar saja. Hasilnya, berat badan saya turun secara alami dan tubuh pun terasa lebih ringan.</p>\n          <p>Memang perlu mencukupi gizi yang dibutuhkan dalam sehari melalui satu kali makan tersebut, dan jika memaksakan diri kondisi tubuh benar-benar bisa memburuk sehingga perlu berhati-hati. Namun, sekarang saya bisa makan sesuai dengan jumlah aktivitas fisik saya sendiri, jadi ke depannya pun saya ingin terus melanjutkan pola hidup ini.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u98df\u4e8b\u306b\u3064\u3044\u3066\u3001\u300c\u79c1\u300d\u306f\u3069\u306e\u3088\u3046\u306b\u8003\u3048\u3066\u3044\u308b\u304b\u3002<br>\n            <em>Bagaimana pendapat \"saya\" mengenai makan?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u4e00\u65e53\u56de\u3054\u98ef\u3092\u98df\u3079\u308b\u3079\u304d\u3060\u3068\u8a00\u308f\u308c\u305f\u304c\u3001\u9762\u5012\u3060\u3063\u305f\u3089\u3001\u98df\u3079\u306a\u304f\u3066\u3082\u3044\u3044\u3002<br><em>Meskipun dikatakan sebaiknya makan 3 kali sehari, kalau merepotkan, tidak makan pun tidak apa-apa.</em></li>\n            <li>\u4e00\u65e53\u56de\u98df\u3079\u305f\u3044\u304c\u3001\u98df\u4e8b\u3088\u308a\u3082\u3001\u4ed5\u4e8b\u306e\u65b9\u304c\u5927\u5207\u3060\u3002<br><em>Ingin makan 3 kali sehari, tetapi pekerjaan lebih penting daripada makan.</em></li>\n            <li>\u4e00\u56de\u306e\u98df\u4e8b\u3067<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092\u3068\u308b\u306e\u306f\u96e3\u3057\u3044\u3057\u3001<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306b\u60aa\u3044\u306e\u3067\u3001\u4e00\u65e53\u56de\u98df\u3079\u305f\u65b9\u304c\u3044\u3044\u3002<br><em>Sulit mencukupi gizi dengan satu kali makan dan buruk bagi kesehatan, jadi lebih baik makan 3 kali sehari.</em></li>\n            <li>\u98df\u4e8b\u306e\u5185\u5bb9\u306b\u6ce8\u610f\u3059\u308b\u5fc5\u8981\u306f\u3042\u308b\u304c\u3001\u4e00\u65e53\u56de\u3054\u98ef\u3092\u98df\u3079\u308b\u5fc5\u8981\u306f\u306a\u3044\u3002<br><em>Meskipun perlu memperhatikan isi/kandungan makanan, tidak harus makan 3 kali sehari.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n          <p><strong>\u8cea\u554f\uff1a</strong>1<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u306b\u3064\u3044\u3066\u3001\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u300d\u306f\u3069\u306e\u3088\u3046\u306b<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u3066\u3044\u308b\u304b\u3002</p>\n          <ul>\n            <li>1\u3000<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>3<ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u3054<ruby>\u98ef<rt>\u306f\u3093</rt></ruby>\u3092<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u308b\u3079\u304d\u3060\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u308f\u308c\u305f\u304c\u3001<u><ruby>\u9762<rt>\u3081\u3093</rt></ruby><ruby>\u5012<rt>\u3069\u3046</rt></ruby>\u3060\u3063\u305f\u3089\u3001<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u306a\u304f\u3066\u3082\u3044\u3044</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u9762<rt>\u3081\u3093</rt></ruby><ruby>\u5012<rt>\u3069\u3046</rt></ruby>\u3060\u3063\u305f\u3089\u3001<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u306a\u304f\u3066\u3082\u3044\u3044\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"kalau merepotkan tidak makan pun tidak apa-apa\".</em></li>\n            <li>2\u3000<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>3<ruby>\u56de<rt>\u304b\u3044</rt></ruby><ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f\u3044\u304c\u3001<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3088\u308a\u3082\u3001<u><ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u306e<ruby>\u65b9<rt>\u307b\u3046</rt></ruby>\u304c<ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3060</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u4ed5<rt>\u3057</rt></ruby><ruby>\u4e8b<rt>\u3054\u3068</rt></ruby>\u306e<ruby>\u65b9<rt>\u307b\u3046</rt></ruby>\u304c<ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5207<rt>\u305b\u3064</rt></ruby>\u3060\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u306a\u3044: <em>Di dalam teks tidak dikatakan \"pekerjaan lebih penting\".</em></li>\n            <li>3\u3000<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u306e<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3067<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u3092\u3068\u308b\u306e\u306f<ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u3044\u3057\u3001<u><ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306b<ruby>\u60aa<rt>\u308f\u308b</rt></ruby>\u3044\u306e\u3067\u3001<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>3<ruby>\u56de<rt>\u304b\u3044</rt></ruby><ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f<ruby>\u65b9<rt>\u307b\u3046</rt></ruby>\u304c\u3044\u3044</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u5065<rt>\u3051\u3093</rt></ruby><ruby>\u5eb7<rt>\u3053\u3046</rt></ruby>\u306b<ruby>\u60aa<rt>\u308f\u308b</rt></ruby>\u3044\u306e\u3067\u3001<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>3<ruby>\u56de<rt>\u304b\u3044</rt></ruby><ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f<ruby>\u65b9<rt>\u307b\u3046</rt></ruby>\u304c\u3044\u3044\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan bahwa pola makan satu kali buruk bagi kesehatan sehingga lebih baik makan 3 kali sehari.</em></li>\n            <li><strong>4\u3000<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u306b<ruby>\u6ce8<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3059\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306f\u3042\u308b\u304c\u3001<ruby>\u4e00<rt>\u3044\u3061</rt></ruby><ruby>\u65e5<rt>\u306b\u3061</rt></ruby>3<ruby>\u56de<rt>\u304b\u3044</rt></ruby>\u3054<ruby>\u98ef<rt>\u306f\u3093</rt></ruby>\u3092<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306f\u306a\u3044\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Penulis menyatakan perlunya mencukupi gizi yang dibutuhkan dalam sehari dan tidak memaksakan diri, serta merasa cocok dengan makan sesuai aktivitas fisik tanpa harus 3 kali sehari.)</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): 4</strong></p>\n        </div>\n      </div>\n\n      <!-- Tanbun (3) -->\n      <div class=\"practice-item\" id=\"tanbun-3\">\n        <h5>\uff083\uff09</h5>\n        <div class=\"reading-passage\">\n          <p><em>\u3053\u308c\u306f\u4f1a\u793e\u306e<ruby>\u5148<rt>\u305b\u3093</rt></ruby><ruby>\u8f29<rt>\u3071\u3044</rt></ruby>\u304b\u3089\u30b8\u30e7\u30f3\u30d8\u3055\u3093\u306b<ruby>\u5c4a<rt>\u3068\u3069</rt></ruby>\u3044\u305f\u30e1\u30fc\u30eb\u3067\u3042\u308b\u3002</em></p>\n          <p>\u30b8\u30e7\u30f3\u30d8\u3055\u3093</p>\n          <p>\u6765\u6708\u306e\u65b0\u5165\u793e\u54e1<ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby>\u4f1a\u306e<ruby>\u6e96<rt>\u3058\u3085\u3093</rt></ruby><ruby>\u5099<rt>\u3073</rt></ruby>\u3092\u3001\u30b8\u30e7\u30f3\u30d8\u3055\u3093\u306b\u304a\u9858\u3044\u3057\u307e\u3059\u3002</p>\n          <p><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3068\u53c2\u52a0\u8005\u306e\u30ea\u30b9\u30c8\u3092\u9001\u308a\u307e\u3059\u306e\u3067\u3001<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3057\u3066\u3001\u307f\u306a\u3055\u3093\u3078\u306e<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby>\u306e\u624b\u7d19\u3092\u4f5c\u3063\u3066\u304f\u3060\u3055\u3044\u3002<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby>\u306b\u306f\u3001\u4f1a\u5834\u306e\u5834\u6240\u3001\u6642\u9593\u3001\u4f1a\u8cbb\u306b\u3064\u3044\u3066\u66f8\u3044\u3066\u304f\u3060\u3055\u3044\u3002</p>\n          <p>\u307e\u305f\u3001\u4f1a\u5834\u3082\u307e\u3060\u4e88\u7d04\u3067\u304d\u3066\u3044\u307e\u305b\u3093\u3002\u5834\u6240\u306f\u6628\u5e74\u3068\u540c\u3058\u30db\u30c6\u30eb\u3067\u3044\u3044\u306e\u3067\u3001\u5348\u524d\u4e2d\u306b\u4e88\u7d04\u3092\u3057\u3066\u304a\u3044\u3066\u304f\u3060\u3055\u3044\u3002</p>\n          <p><ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u306e\u4f5c\u6210\u306e\u624b\u4f1d\u3044\u304c\u5fc5\u8981\u306a\u5834\u5408\u306f\u3001\u4eca\u65e5\u306e\u591c\u307e\u3067\u306b\u9023\u7d61\u3092\u304a\u9858\u3044\u3057\u307e\u3059\u3002</p>\n          <p>\u3082\u3057\u3001\u308f\u304b\u3089\u306a\u3044\u3053\u3068\u304c\u3042\u308c\u3070\u4f55\u3067\u3082\u805e\u3044\u3066\u304f\u3060\u3055\u3044\u3002</p>\n          <p style=\"text-align: right;\"><ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby></p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p><em>Ini adalah email yang diterima Sdri. Jeonghye dari senior di perusahaannya.</em></p>\n          <p>Sdri. Jeonghye,</p>\n          <p>Saya mohon bantuan Sdri. Jeonghye untuk persiapan pesta penyambutan karyawan baru bulan depan.</p>\n          <p>Saya akan mengirimkan dokumen dan daftar peserta, jadi silakan diperiksa lalu buatlah surat pemberitahuan untuk semuanya. Pada pemberitahuan tersebut, tolong tuliskan lokasi tempat acara, waktu, dan biaya partisipasi.</p>\n          <p>Selain itu, tempat acaranya juga belum dipesan. Lokasinya boleh di hotel yang sama seperti tahun lalu, jadi tolong pesan terlebih dahulu pada pagi hari (sebelum tengah hari).</p>\n          <p>Jika memerlukan bantuan dalam pembuatan surat pemberitahuan, mohon hubungi saya paling lambat malam ini.</p>\n          <p>Jika ada hal yang tidak dimengerti, silakan tanyakan apa saja.</p>\n          <p style=\"text-align: right;\">Yamamoto</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u30b8\u30e7\u30f3\u30d8\u3055\u3093\u304c\u3053\u306e\u30e1\u30fc\u30eb\u3067<ruby>\u983c<rt>\u305f\u306e</rt></ruby>\u307e\u308c\u3066\u3044\u308b\u3053\u3068\u306f\u3069\u308c\u304b\u3002<br>\n            <em>Manakah hal yang diminta kepada Sdri. Jeonghye dalam email ini?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u65b0\u5165\u793e\u54e1<ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby>\u4f1a\u306e<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3001\u4f1a\u5834\u306e\u5834\u6240\u306e\u307b\u304b\u306b\u53c2\u52a0\u8005\u306e\u540d\u524d\u3082\u66f8\u304f\u3002<br><em>Menuliskan nama para peserta selain lokasi tempat acara pada surat pemberitahuan pesta penyambutan karyawan baru.</em></li>\n            <li>\u65b0\u5165\u793e\u54e1<ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby>\u4f1a\u306e\u4f1a\u5834\u3092\u4e88\u7d04\u3057\u305f\u3042\u3068\u3067\u3001\u53c2\u52a0\u8005\u306b\u9001\u308b<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u3092\u4f5c\u308b\u3002<br><em>Setelah memesan tempat pesta penyambutan karyawan baru, membuat surat pemberitahuan yang akan dikirim kepada para peserta.</em></li>\n            <li>\u65b0\u5165\u793e\u54e1<ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby>\u4f1a\u306e\u4f1a\u5834\u3092\u4e88\u7d04\u3057\u305f\u3089\u3001\u591c\u307e\u3067\u306b<ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b\u9023\u7d61\u3059\u308b\u3002<br><em>Jika sudah memesan tempat pesta penyambutan karyawan baru, menghubungi Pak/Sdr. Yamamoto paling lambat malam hari.</em></li>\n            <li>\u65b0\u5165\u793e\u54e1<ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby>\u4f1a\u306e<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3068\u53c2\u52a0\u8005\u3092<ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b\u9023\u7d61\u3057\u3066\u805e\u304f\u3002<br><em>Menghubungi Pak/Sdr. Yamamoto untuk menanyakan dokumen dan peserta pesta penyambutan karyawan baru.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n          <p><strong>\u8cea\u554f\uff1a</strong>1\u30b8\u30e7\u30f3\u30d8\u3055\u3093\u304c\u3053\u306e\u30e1\u30fc\u30eb\u3067<ruby>\u983c<rt>\u305f\u306e</rt></ruby>\u307e\u308c\u3066\u3044\u308b\u3053\u3068\u306f\u3069\u308c\u304b\u3002</p>\n          <ul>\n            <li>1\u3000<ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u54e1<rt>\u3044\u3093</rt></ruby><ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u306b\u3001<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306e<ruby>\u5834<rt>\u3070</rt></ruby><ruby>\u6240<rt>\u3057\u3087</rt></ruby>\u306e\u307b\u304b\u306b<u><ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby><ruby>\u8005<rt>\u3057\u3083</rt></ruby>\u306e<ruby>\u540d<rt>\u306a</rt></ruby><ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u3082<ruby>\u66f8<rt>\u304b</rt></ruby>\u304f</u>\u3002\uff08\u00d7\uff09<br><ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u306b<ruby>\u66f8<rt>\u304b</rt></ruby>\u304f\u306e\u306f\u3001\u300c<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u306e<ruby>\u5834<rt>\u3070</rt></ruby><ruby>\u6240<rt>\u3057\u3087</rt></ruby>\u300d\u300c<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby>\u300d\u300c<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8cbb<rt>\u3072</rt></ruby>\u300d: <em>Yang ditulis dalam surat pemberitahuan adalah \"lokasi tempat acara\", \"waktu\", dan \"biaya partisipasi\".</em></li>\n            <li><strong>2\u3000<ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u54e1<rt>\u3044\u3093</rt></ruby><ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u3092<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u7d04<rt>\u3084\u304f</rt></ruby>\u3057\u305f\u3042\u3068\u3067\u3001<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby><ruby>\u8005<rt>\u3057\u3083</rt></ruby>\u306b<ruby>\u9001<rt>\u304a\u304f</rt></ruby>\u308b<ruby>\u6848<rt>\u3042\u3093</rt></ruby><ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby>\u3092<ruby>\u4f5c<rt>\u3064\u304f</rt></ruby>\u308b\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Karena tempat acara belum dipesan, Jeonghye perlu memesannya terlebih dahulu agar bisa mencantumkan lokasi tempat acara pada surat pemberitahuan.)</em></li>\n            <li>3\u3000<ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u54e1<rt>\u3044\u3093</rt></ruby><ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u5834<rt>\u3058\u3087\u3046</rt></ruby>\u3092<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u7d04<rt>\u3084\u304f</rt></ruby>\u3057\u305f\u3089\u3001<u><ruby>\u591c<rt>\u3088\u308b</rt></ruby>\u307e\u3067\u306b<ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3059\u308b</u>\u3002\uff08\u00d7\uff09<br><ruby>\u624b<rt>\u3066</rt></ruby><ruby>\u4f1d<rt>\u3064\u3060</rt></ruby>\u3044\u304c<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306a<ruby>\u5834<rt>\u3070</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby>\u3060\u3051\u3001<ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3059\u308b: <em>Hanya menghubungi Pak/Sdr. Yamamoto apabila memerlukan bantuan (pembuatan surat pemberitahuan).</em></li>\n            <li>4\u3000<ruby>\u65b0<rt>\u3057\u3093</rt></ruby><ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u54e1<rt>\u3044\u3093</rt></ruby><ruby>\u6b53<rt>\u304b\u3093</rt></ruby><ruby>\u8fce<rt>\u3052\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306e<ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3068<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby><ruby>\u8005<rt>\u3057\u3083</rt></ruby>\u3092<u><ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3057\u3066<ruby>\u805e<rt>\u304d</rt></ruby>\u304f</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306b<ruby>\u9023<rt>\u308c\u3093</rt></ruby><ruby>\u7d61<rt>\u3089\u304f</rt></ruby>\u3057\u3066<ruby>\u805e<rt>\u304d</rt></ruby>\u304f\u300d\u3067\u306f\u306a\u304f\u3001\u30e1\u30fc\u30eb\u3068\u3044\u3063\u3057\u3087\u306b<ruby>\u5c4a<rt>\u3068\u3069</rt></ruby>\u3044\u3066\u3044\u308b: <em>Bukan \"menghubungi Yamamoto untuk menanyakan\", melainkan dokumen dan daftar peserta sudah dikirim bersama email tersebut.</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): 2</strong></p>\n        </div>\n      </div>\n\n      <!-- Tanbun (4) -->\n      <div class=\"practice-item\" id=\"tanbun-4\">\n        <h5>\uff084\uff09</h5>\n        <div class=\"reading-passage\">\n          <p><em>\u3053\u308c\u306f\u56f3\u66f8\u9928\u306b\u306f\u3063\u3066\u3042\u308b\u304a\u77e5\u3089\u305b\u3067\u3042\u308b\u3002</em></p>\n          <p>\u5229\u7528\u8005\u306e\u307f\u306a\u3055\u3093\u3078</p>\n          <p>\u68ee\u56f3\u66f8\u9928\u3067\u306f\u3001\u6708\u306b3\u56de\u300e\u6620\u753b\u4f1a\u300f\u3092\u884c\u3063\u3066\u3044\u307e\u3059\u3002</p>\n          <p>\u9031\u672b\u306f\u3001\u6620\u753b\u4f1a\u306e\u3042\u3068\u300e\u304a\u306f\u306a\u3057\u4f1a\u300f\u3082\u3042\u308a\u307e\u3059\u3002\u304a\u83d3\u5b50\u3092\u98df\u3079\u306a\u304c\u3089\u6620\u753b\u306b\u3064\u3044\u3066\u8a71\u3057\u307e\u3057\u3087\u3046\u3002\u65e5\u7a0b\u306f\u4ee5\u4e0b\u306e\u901a\u308a\u3067\u3059\u3002</p>\n          <ul>\n            <li>11\u670813\u65e5\uff08\u571f\uff0913\uff1a30\uff5e16\uff1a30\uff08\u68ee\u56f3\u66f8\u9928\u4e00\u968e\u3000\u5b50\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\uff09</li>\n            <li>11\u670821\u65e5\uff08\u65e5\uff0915\uff1a30\uff5e17\uff1a30\uff08\u68ee\u56f3\u66f8\u9928\u4e09\u968e\u3000\u5b50\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\uff09</li>\n            <li>11\u670829\u65e5\uff08\u6708\uff0910\uff1a30\uff5e12\uff1a30\uff08\u68ee\u56f3\u66f8\u9928\u4e09\u968e\u3000\u4f1a\u8b70\u5ba4\uff09</li>\n          </ul>\n          <p>\u307e\u305f\u3001\u68ee\u56f3\u66f8\u9928\u4e8c\u968e\u306e\u307e\u3093\u304c\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u3067\u306f\u4ea4\u6d41\u4f1a\u3092\u884c\u3063\u3066\u3044\u307e\u3059\u306e\u3067\u3001\u9593\u9055\u3048\u306a\u3044\u3088\u3046\u304a\u6c17\u3092\u4ed8\u3051\u304f\u3060\u3055\u3044\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p><em>Ini adalah pengumuman yang tertempel di perpustakaan.</em></p>\n          <p>Kepada Para Pengunjung,</p>\n          <p>Di Perpustakaan Mori, kami mengadakan \"Acara Pemutaran Film\" 3 kali dalam sebulan.</p>\n          <p>Pada akhir pekan, setelah acara pemutaran film juga ada \"Sesi Bincang-Bincang (Ohanashi-kai)\". Mari mengobrol tentang film sambil makan camilan. Jadwalnya adalah sebagai berikut:</p>\n          <ul>\n            <li>13 November (Sabtu) 13.30-16.30 (Perpustakaan Mori Lantai 1, Ruang Anak)</li>\n            <li>21 November (Minggu) 15.30-17.30 (Perpustakaan Mori Lantai 3, Ruang Anak)</li>\n            <li>29 November (Senin) 10.30-12.30 (Perpustakaan Mori Lantai 3, Ruang Rapat)</li>\n          </ul>\n          <p>Selain itu, di Ruang Manga Lantai 2 Perpustakaan Mori sedang diadakan acara pertemuan ramah tamah (koryukai), jadi mohon berhati-hati agar tidak salah tempat.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u304a\u306f\u306a\u3057\u4f1a\u306b\u53c2\u52a0\u3059\u308b\u306b\u306f\u3069\u3053\u306b\u884c\u3051\u3070\u3088\u3044\u3067\u3059\u304b\u3002<br>\n            <em>Untuk mengikuti Sesi Bincang-Bincang (Ohanashi-kai), harus pergi ke mana?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u4e00\u968e\u5b50\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u304b\u4e09\u968e\u5b50\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby><br><em>Ruang Anak Lantai 1 atau Ruang Anak Lantai 3</em></li>\n            <li>\u4e09\u968e\u4f1a\u8b70\u5ba4<br><em>Ruang Rapat Lantai 3</em></li>\n            <li>\u4e00\u968e\u5b50\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u304b\u4e09\u968e\u4f1a\u8b70\u5ba4<br><em>Ruang Anak Lantai 1 atau Ruang Rapat Lantai 3</em></li>\n            <li>\u4e8c\u968e\u306e\u307e\u3093\u304c\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby><br><em>Ruang Manga di Lantai 2</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n          <p><strong>\u8cea\u554f\uff1a</strong>1\u304a\u306f\u306a\u3057<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u306b<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby>\u3059\u308b\u306b\u306f\u3069\u3053\u306b<ruby>\u884c<rt>\u3044</rt></ruby>\u3051\u3070\u3088\u3044\u3067\u3059\u304b\u3002</p>\n          <ul>\n            <li><strong>1\u3000<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u968e<rt>\u304b\u3044</rt></ruby><ruby>\u5b50<rt>\u3053</rt></ruby>\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u304b<ruby>\u4e09<rt>\u3055\u3093</rt></ruby><ruby>\u968e<rt>\u304c\u3044</rt></ruby><ruby>\u5b50<rt>\u3053</rt></ruby>\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Karena Sesi Bincang-Bincang hanya diadakan pada akhir pekan, Sabtu dan Minggu, yang bertempat di Ruang Anak Lantai 1 dan Ruang Anak Lantai 3.)</em></li>\n            <li>2\u3000<u><ruby>\u4e09<rt>\u3055\u3093</rt></ruby><ruby>\u968e<rt>\u304c\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u4e09<rt>\u3055\u3093</rt></ruby><ruby>\u968e<rt>\u304c\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby>\u300d\u3067\u300c<ruby>\u6620<rt>\u3048\u3044</rt></ruby><ruby>\u753b<rt>\u304c</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u300d\u3092<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u3046<ruby>\u65e5<rt>\u3072</rt></ruby>\u306f<ruby>\u6708<rt>\u3052\u3064</rt></ruby><ruby>\u66dc<rt>\u3088\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u306a\u306e\u3067\u3001\u300c\u304a\u306f\u306a\u3057<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u300d\u306f<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u308f\u308c\u306a\u3044: <em>Hari pelaksanaan \"Acara Pemutaran Film\" di \"Ruang Rapat Lantai 3\" adalah hari Senin, sehingga \"Sesi Bincang-Bincang\" tidak diadakan (karena hanya akhir pekan).</em></li>\n            <li>3\u3000<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u968e<rt>\u304b\u3044</rt></ruby><ruby>\u5b50<rt>\u3053</rt></ruby>\u3069\u3082\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u304b<u><ruby>\u4e09<rt>\u3055\u3093</rt></ruby><ruby>\u968e<rt>\u304c\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u4e09<rt>\u3055\u3093</rt></ruby><ruby>\u968e<rt>\u304c\u3044</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby><ruby>\u8b70<rt>\u304e</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby>\u300d\u3067\u300c<ruby>\u6620<rt>\u3048\u3044</rt></ruby><ruby>\u753b<rt>\u304c</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u300d\u3092<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u3046<ruby>\u65e5<rt>\u3072</rt></ruby>\u306f<ruby>\u6708<rt>\u3052\u3064</rt></ruby><ruby>\u66dc<rt>\u3088\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u306a\u306e\u3067\u3001\u300c\u304a\u306f\u306a\u3057<ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u300d\u306f<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u308f\u308c\u306a\u3044: <em>Di \"Ruang Rapat Lantai 3\" acaranya pada hari Senin, sehingga \"Sesi Bincang-Bincang\" tidak diadakan.</em></li>\n            <li>4\u3000<u><ruby>\u4e8c<rt>\u306b</rt></ruby><ruby>\u968e<rt>\u304b\u3044</rt></ruby>\u306e\u307e\u3093\u304c\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby></u>\uff08\u00d7\uff09<br>\u300c<ruby>\u4e8c<rt>\u306b</rt></ruby><ruby>\u968e<rt>\u304b\u3044</rt></ruby>\u306e\u307e\u3093\u304c\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u300d\u306f\u3001<ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u6d41<rt>\u308a\u3085\u3046</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u3092<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u3046<ruby>\u5834<rt>\u3070</rt></ruby><ruby>\u6240<rt>\u3057\u3087</rt></ruby>: <em>\"Ruang Manga di Lantai 2\" adalah tempat diselenggarakannya acara ramah tamah (koryukai).</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): 1</strong></p>\n        </div>\n      </div>\n    </div>\n\n    <!-- ===== MASALAH 5: CHUUBUN ===== -->\n    <div class=\"reading-section\" id=\"reading-chuubun\">\n      <h4>5. Pemahaman Isi \u00b7 Teks Sedang (<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09)</h4>\n\n      <div class=\"info-box\">\n        <p>\n          <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>5\u3067\u306f\u3001<ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff08400<ruby>\u5b57<rt>\u3058</rt></ruby><ruby>\u7a0b<rt>\u3066\u3044</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\uff09\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u307e\u3059\u3002\u305d\u3057\u3066\u3001<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306e<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u3001<ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u56e0<rt>\u3044\u3093</rt></ruby>\u3084<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u306b\u3064\u3044\u3066\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u306f2\u3064\u306e<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c\u3042\u308a\u30011\u3064\u306e<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3054\u3068\u306b3\u3064\u306e<ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<br>\n          <em>Pada Bagian 5 (Mondai 5), Anda akan membaca teks sedang (sekitar 400 huruf). Soal yang keluar menanyakan pemikiran penulis teks, serta sebab atau alasan. Pemahaman Isi (Teks Sedang) memiliki 2 bacaan utama, dan tiap bacaan memiliki 3 pertanyaan.</em>\n        </p>\n        <p>\n          <strong>\u554f\u984c5</strong>\u3000\u3064\u304e\u306e\uff081\uff09\u3068\uff082\uff09\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092\u8aad\u3093\u3067\u3001\u8cea\u554f\u306b\u7b54\u3048\u306a\u3055\u3044\u3002\u7b54\u3048\u306f\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br>\n          <em><strong>Soal 5:</strong> Bacalah teks (1) dan (2) berikut ini, lalu jawablah pertanyaannya. Pilihlah satu jawaban yang paling tepat dari pilihan 1, 2, 3, atau 4.</em>\n        </p>\n      </div>\n\n      <!-- Chuubun (1) -->\n      <div class=\"practice-item\" id=\"chuubun-1\">\n        <h5>\uff081\uff09</h5>\n        <div class=\"reading-passage\">\n          <p>\u79c1\u306f\u96fb\u8eca\u306e\u65c5\u304c\u597d\u304d\u3067\u3059\u3002\u89b3\u5149\u5730\u3067\u5199\u771f\u3092<ruby>\u64ae<rt>\u3068</rt></ruby>\u3063\u305f\u308a\u3001\u8cb7\u3044\u7269\u3092\u3057\u305f\u308a\u3059\u308b\u306e\u3082\u597d\u304d\u3067\u3059\u304c\u3001\u305d\u308c\u3060\u3051\u3067\u306f\u306a\u304f\u3001\u96fb\u8eca\u306b\u4e57\u308a\u306a\u304c\u3089<ruby>\u666f\u8272<rt>\u3051\u3057\u304d</rt></ruby>\u3092\u898b\u305f\u308a\u3001\u76ee\u7684\u5730\u306b\u7740\u3044\u305f\u3089\u4f55\u3092\u3059\u308b\u304b\u8003\u3048\u308b\u306e\u304c\u597d\u304d\u306a\u3093\u3067\u3059\u3002</p>\n          <p>\u4eca\u65e5\u3082\u5317\u99c5\u306b\u5411\u304b\u3046\u305f\u3081\u306b\u96fb\u8eca\u306b\u4e57\u308a\u307e\u3057\u305f\u3002\u3057\u304b\u3057\u3001\u96fb\u8eca\u304c\u52d5\u304d\u51fa\u3057\u3066\u3057\u3070\u3089\u304f<ruby>\u7d4c<rt>\u305f</rt></ruby>\u3063\u3066\u304b\u3089\u79c1\u306f\u2460<u>\u5927\u5909\u306a\u3053\u3068\u306b\u6c17\u3065\u304d\u307e\u3057\u305f</u>\u3002\u96fb\u8eca\u306f\u79c1\u306e\u884c\u304d\u305f\u3044\u65b9\u5411\u3068\u53cd\u5bfe\u306b\u5411\u304b\u3063\u3066\u8d70\u3063\u3066\u3044\u305f\u306e\u3067\u3059\u3002<ruby>\u9a5a<rt>\u304a\u3069\u308d</rt></ruby>\u3044\u3066\u3001\u3082\u3046\u4e00\u5ea6\u3088\u304f\u8abf\u3079\u308b\u3068\u3001\u5317\u99c5\u306b\u884c\u304f\u96fb\u8eca\u3068\u5357\u99c5\u306b\u884c\u304f\u96fb\u8eca\u304c\u540c\u3058\u6642\u9593\u306b\u51fa\u767a\u3057\u3066\u3044\u307e\u3057\u305f\u3002\u4eca\u304b\u3089<ruby>\u623b<rt>\u3082\u3069</rt></ruby>\u3063\u3066\u3082\u3001\u5317\u99c5\u3078\u884c\u304f\u96fb\u8eca\u304c\u6765\u308b\u306e\u306f3\u6642\u9593\u5f8c\u3067\u3057\u305f\u3002</p>\n          <p>\u3044\u3064\u3082\u7d30\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092\u5fd8\u308c\u3066\u3057\u307e\u3044\u3001\u76ee\u7684\u5730\u306b\u7740\u304f\u307e\u3067\u306b\u6642\u9593\u304c\u304b\u304b\u3063\u3066\u3057\u307e\u3046\u306e\u3067\u3059\u3002\u9053\u3092\u9593\u9055\u3048\u308b\u305f\u3073\u306b\u2461<u>\u305d\u3093\u306a\u81ea\u5206\u306e\u6027\u683c\u3092\u76f4\u3057\u305f\u3044</u>\u3068\u601d\u3063\u3066\u3044\u307e\u3059\u3002</p>\n          <p>\u3057\u304b\u3057\u3001\u76ee\u7684\u5730\u3068\u306f\u9055\u3046\u5834\u6240\u3067\u3082\u65b0\u3057\u3044\u767a\u898b\u304c\u3042\u308a\u307e\u3059\u3002\u306a\u306e\u3067\u4f55\u5ea6\u9053\u3092\u9593\u9055\u3048\u3066\u3082\u3001\u65c5\u304c<ruby>\u5acc<rt>\u304d\u3089</rt></ruby>\u3044\u306b\u306a\u308b\u3053\u3068\u306f\u306a\u3044\u3068\u601d\u3044\u307e\u3059\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p>Saya menyukai perjalanan dengan kereta api. Saya suka mengambil foto maupun berbelanja di tempat wisata, tetapi bukan hanya itu saja, saya juga suka melihat pemandangan sambil naik kereta dan membayangkan apa yang akan saya lakukan setelah tiba di tempat tujuan.</p>\n          <p>Hari ini pun saya naik kereta untuk pergi menuju Stasiun Kita (Utara). Akan tetapi, beberapa saat setelah kereta mulai bergerak, saya \u2460<u>menyadari suatu hal yang gawat</u>. Kereta tersebut melaju ke arah yang berlawanan dengan arah yang ingin saya tuju. Karena terkejut, saya memeriksanya baik-baik sekali lagi, ternyata kereta menuju Stasiun Kita dan kereta menuju Stasiun Minami (Selatan) berangkat pada jam yang sama. Kalaupun saya kembali sekarang, kereta yang menuju Stasiun Kita baru akan datang 3 jam kemudian.</p>\n          <p>Saya memang selalu lupa melakukan pemeriksaan secara detail, sehingga memakan waktu lama untuk sampai ke tempat tujuan. Setiap kali salah jalan, saya berpikir \u2461<u>ingin memperbaiki sifat diri saya yang seperti itu</u>.</p>\n          <p>Akan tetapi, di tempat yang berbeda dari tujuan pun selalu ada penemuan baru. Oleh karena itu, berapa kali pun saya salah jalan, saya rasa saya tidak akan pernah membenci perjalanan.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u2460<u>\u5927\u5909\u306a\u3053\u3068\u306b\u6c17\u3065\u304d\u307e\u3057\u305f</u>\u3068\u3042\u308b\u304c\u3001\u3069\u306e\u3088\u3046\u306a\u3053\u3068\u304b\u3002<br>\n            <em>Terdapat kalimat \u2460<u>\"menyadari suatu hal yang gawat\"</u>, hal seperti apakah itu?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u4e8c\u672c\u306e\u96fb\u8eca\u304c\u3001\u540c\u3058\u6642\u9593\u306b\u51fa\u767a\u3057\u306a\u304b\u3063\u305f\u3053\u3068<br><em>Bahwa dua buah kereta tidak berangkat pada jam yang sama.</em></li>\n            <li>\u4e57\u3063\u305f\u96fb\u8eca\u304c\u3001\u76ee\u7684\u5730\u3068\u306f\u53cd\u5bfe\u306b\u9032\u3093\u3067\u3044\u305f\u3053\u3068<br><em>Bahwa kereta yang dinaiki melaju ke arah yang berlawanan dengan tempat tujuan.</em></li>\n            <li>\u4e57\u3063\u305f\u96fb\u8eca\u306e\u51fa\u767a\u304c\u30013\u6642\u9593\u9045\u308c\u3066\u3044\u305f\u3053\u3068<br><em>Bahwa keberangkatan kereta yang dinaiki terlambat 3 jam.</em></li>\n            <li>\u4e57\u3063\u3066\u3044\u308b\u96fb\u8eca\u304c\u3001\u3057\u3070\u3089\u304f\u52d5\u304b\u306a\u304b\u3063\u305f\u3053\u3068<br><em>Bahwa kereta yang sedang dinaiki tidak bergerak untuk beberapa saat.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>2</strong>\u3000\u2461<u>\u305d\u3093\u306a\u81ea\u5206\u306e\u6027\u683c\u3092\u76f4\u3057\u305f\u3044</u>\u3068\u3042\u308b\u304c\u3001\u305d\u308c\u306f\u306a\u305c\u304b\u3002<br>\n            <em>Terdapat kalimat \u2461<u>\"ingin memperbaiki sifat diri saya yang seperti itu\"</u>, mengapakah demikian?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u76ee\u7684\u5730\u306b\u5230\u7740\u3059\u308b\u307e\u3067\u3001\u65c5\u3092\u697d\u3057\u3080\u3053\u3068\u304c\u51fa\u6765\u306a\u3044\u304b\u3089\u3002<br><em>Karena sampai tiba di tempat tujuan, tidak bisa menikmati perjalanan.</em></li>\n            <li>\u76ee\u7684\u5730\u306b\u5230\u7740\u3059\u308b\u524d\u306b\u3001<ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066\u697d\u3057\u3081\u306a\u3044\u304b\u3089\u3002<br><em>Karena sebelum tiba di tempat tujuan, sudah kelelahan dan tidak bisa bersenang-senang.</em></li>\n            <li>\u7d30\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092\u5fd8\u308c\u3066\u3057\u307e\u3044\u3001\u76ee\u7684\u5730\u306b\u306a\u304b\u306a\u304b\u5230\u7740\u3067\u304d\u306a\u3044\u304b\u3089\u3002<br><em>Karena lupa melakukan pemeriksaan detail, sehingga tidak kunjung bisa sampai di tempat tujuan.</em></li>\n            <li>\u7d30\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092\u3057\u3059\u304e\u3066\u3001\u76ee\u7684\u5730\u306b\u4e88\u5b9a\u3088\u308a\u65e9\u304f\u5230\u7740\u3057\u3066\u3057\u307e\u3046\u304b\u3089\u3002<br><em>Karena terlalu berlebihan memeriksa hal detail, sehingga sampai di tempat tujuan lebih cepat dari jadwal.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>3</strong>\u3000\u65c5\u3092\u3059\u308b\u3053\u3068\u306b\u3064\u3044\u3066\u300c\u79c1\u300d\u306f\u3069\u3046\u601d\u3063\u3066\u3044\u308b\u304b\u3002<br>\n            <em>Bagaimana pendapat \"saya\" tentang melakukan perjalanan?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u65c5\u3092\u597d\u304d\u306b\u306a\u308c\u308b\u3088\u3046\u306b\u3001\u65b0\u3057\u3044\u767a\u898b\u3092\u3057\u306a\u304c\u3089\u65c5\u3092\u3059\u308b\u3060\u308d\u3046\u3002<br><em>Agar bisa menyukai perjalanan, ia akan melakukan perjalanan sambil mencari penemuan baru.</em></li>\n            <li>\u307e\u305f\u9053\u3092\u9593\u9055\u3048\u308b\u3068\u601d\u3046\u304c\u3001\u3053\u308c\u304b\u3089\u3082\u697d\u3057\u304f\u65c5\u3092\u3059\u308b\u3060\u308d\u3046\u3002<br><em>Meskipun merasa akan salah jalan lagi, ke depannya pun ia akan tetap melakukan perjalanan dengan gembira.</em></li>\n            <li>\u4eca\u5ea6\u304b\u3089\u9053\u3092\u9593\u9055\u3048\u306a\u3044\u3088\u3046\u306b\u3001\u3082\u3063\u3068\u8abf\u3079\u3066\u304b\u3089\u65c5\u3092\u3059\u308b\u3060\u308d\u3046\u3002<br><em>Agar lain kali tidak salah jalan, ia akan melakukan perjalanan setelah mencari tahu lebih banyak.</em></li>\n            <li>\u4eca\u3088\u308a\u3082\u65c5\u304c\u697d\u3057\u304f\u306a\u308b\u3088\u3046\u306b\u3001\u6642\u9593\u306b\u6ce8\u610f\u3057\u3066\u65c5\u3092\u3059\u308b\u3060\u308d\u3046\u3002<br><em>Agar perjalanan menjadi lebih menyenangkan daripada sekarang, ia akan melakukan perjalanan sambil memperhatikan waktu.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n\n          <p><strong>1\u3000\u2460<u><ruby>\u5927<rt>\u305f\u3044</rt></ruby><ruby>\u5909<rt>\u3078\u3093</rt></ruby>\u306a\u3053\u3068\u306b<ruby>\u6c17<rt>\u304d</rt></ruby>\u3065\u304d\u307e\u3057\u305f</u>\u3068\u3042\u308b\u304c\u3001\u3069\u306e\u3088\u3046\u306a\u3053\u3068\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u4e8c<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby>\u306e<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby>\u304c\u3001<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby>\u306b<ruby>\u51fa<rt>\u3057\u3085\u3063</rt></ruby><ruby>\u767a<rt>\u3071\u3064</rt></ruby>\u3057\u306a\u304b\u3063\u305f\u3053\u3068\uff08\u00d7\uff09</li>\n            <li><strong>2\u3000<ruby>\u4e57<rt>\u306e</rt></ruby>\u3063\u305f<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby>\u304c\u3001<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u3068\u306f<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby>\u306b<ruby>\u9032<rt>\u3059\u3059</rt></ruby>\u3093\u3067\u3044\u305f\u3053\u3068\uff08\u3007\uff09</strong></li>\n            <li>3\u3000<ruby>\u4e57<rt>\u306e</rt></ruby>\u3063\u305f<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby>\u306e<ruby>\u51fa<rt>\u3057\u3085\u3063</rt></ruby><ruby>\u767a<rt>\u3071\u3064</rt></ruby>\u304c\u30013<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby><ruby>\u9045<rt>\u304a\u304f</rt></ruby>\u308c\u3066\u3044\u305f\u3053\u3068\uff08\u00d7\uff09</li>\n            <li>4\u3000<ruby>\u4e57<rt>\u306e</rt></ruby>\u3063\u3066\u3044\u308b<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby>\u304c\u3001\u3057\u3070\u3089\u304f<ruby>\u52d5<rt>\u3046\u3054</rt></ruby>\u304b\u306a\u304b\u3063\u305f\u3053\u3068\uff08\u00d7\uff09</li>\n          </ul>\n          <p>\n            \u203b\u300c<ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8eca<rt>\u3057\u3083</rt></ruby>\u306f<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u306e<ruby>\u884c<rt>\u3044</rt></ruby>\u304d\u305f\u3044<ruby>\u65b9<rt>\u307b\u3046</rt></ruby><ruby>\u5411<rt>\u3053\u3046</rt></ruby>\u3068<ruby>\u53cd<rt>\u306f\u3093</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby>\u306b<ruby>\u5411<rt>\u3080</rt></ruby>\u304b\u3063\u3066<ruby>\u8d70<rt>\u306f\u3057</rt></ruby>\u3063\u3066\u3044\u305f\u306e\u3067\u3059\u3002\u300d\u304c<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3060\u304b\u30892\u304c<ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3002<br>\n            <em>Catatan: Karena alasannya adalah kalimat \"Kereta tersebut melaju ke arah yang berlawanan dengan arah yang ingin saya tuju\", maka pilihan <strong>2</strong> adalah jawaban yang benar.</em>\n          </p>\n\n          <p><strong>2\u3000\u2461<u>\u305d\u3093\u306a<ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u306e<ruby>\u6027<rt>\u305b\u3044</rt></ruby><ruby>\u683c<rt>\u304b\u304f</rt></ruby>\u3092<ruby>\u76f4<rt>\u306a\u304a</rt></ruby>\u3057\u305f\u3044</u>\u3068\u3042\u308b\u304c\u3001\u305d\u308c\u306f\u306a\u305c\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u306b<ruby>\u5230<rt>\u3068\u3046</rt></ruby><ruby>\u7740<rt>\u3061\u3083\u304f</rt></ruby>\u3059\u308b\u307e\u3067\u3001<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3080\u3053\u3068\u304c<ruby>\u51fa<rt>\u3067</rt></ruby><ruby>\u6765<rt>\u304d</rt></ruby>\u306a\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>2\u3000<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u306b<ruby>\u5230<rt>\u3068\u3046</rt></ruby><ruby>\u7740<rt>\u3061\u3083\u304f</rt></ruby>\u3059\u308b<ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b\u3001<ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3081\u306a\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li><strong>3\u3000<ruby>\u7d30<rt>\u3053\u307e</rt></ruby>\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092<ruby>\u5fd8<rt>\u308f\u3059</rt></ruby>\u308c\u3066\u3057\u307e\u3044\u3001<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u306b\u306a\u304b\u306a\u304b<ruby>\u5230<rt>\u3068\u3046</rt></ruby><ruby>\u7740<rt>\u3061\u3083\u304f</rt></ruby>\u3067\u304d\u306a\u3044\u304b\u3089\u3002\uff08\u3007\uff09</strong></li>\n            <li>4\u3000<ruby>\u7d30<rt>\u3053\u307e</rt></ruby>\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092\u3057\u3059\u304e\u3066\u3001<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u306b<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u5b9a<rt>\u3066\u3044</rt></ruby>\u3088\u308a<ruby>\u65e9<rt>\u306f\u3084</rt></ruby>\u304f<ruby>\u5230<rt>\u3068\u3046</rt></ruby><ruby>\u7740<rt>\u3061\u3083\u304f</rt></ruby>\u3057\u3066\u3057\u307e\u3046\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n          </ul>\n          <p>\n            \u203b\u300c\u3044\u3064\u3082<ruby>\u7d30<rt>\u3053\u307e</rt></ruby>\u304b\u3044<ruby>\u78ba<rt>\u304b\u304f</rt></ruby><ruby>\u8a8d<rt>\u306b\u3093</rt></ruby>\u3092<ruby>\u5fd8<rt>\u308f\u3059</rt></ruby>\u308c\u3066\u3057\u307e\u3044\u3001<ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u7684<rt>\u3066\u304d</rt></ruby><ruby>\u5730<rt>\u3061</rt></ruby>\u306b<ruby>\u7740<rt>\u3064</rt></ruby>\u304f\u307e\u3067\u306b<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby>\u304c\u304b\u304b\u3063\u3066\u3057\u307e\u3046\u306e\u3067\u3059\u3002\u300d\u304c<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3060\u304b\u30893\u304c<ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3002<br>\n            <em>Catatan: Karena alasannya adalah kalimat \"Saya selalu lupa melakukan pemeriksaan secara detail, sehingga memakan waktu lama untuk sampai ke tempat tujuan\", maka pilihan <strong>3</strong> adalah jawaban yang benar.</em>\n          </p>\n\n          <p><strong>3\u3000<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092\u3059\u308b\u3053\u3068\u306b\u3064\u3044\u3066\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u300d\u306f\u3069\u3046<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3063\u3066\u3044\u308b\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<u><ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092<ruby>\u597d<rt>\u3059</rt></ruby>\u304d\u306b\u306a\u308c\u308b\u3088\u3046\u306b</u>\u3001<ruby>\u65b0<rt>\u3042\u305f\u3089</rt></ruby>\u3057\u3044<ruby>\u767a<rt>\u306f\u3063</rt></ruby><ruby>\u898b<rt>\u3051\u3093</rt></ruby>\u3092\u3057\u306a\u304c\u3089<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092\u3059\u308b\u3060\u308d\u3046\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092<ruby>\u597d<rt>\u3059</rt></ruby>\u304d\u306b\u306a\u308c\u308b\u3088\u3046\u306b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"agar bisa menyukai perjalanan\" (penulis memang sudah menyukai perjalanan sejak awal).</em></li>\n            <li><strong>2\u3000\u307e\u305f<ruby>\u9053<rt>\u307f\u3061</rt></ruby>\u3092<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3048\u308b\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3046\u304c\u3001\u3053\u308c\u304b\u3089\u3082<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u304f<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092\u3059\u308b\u3060\u308d\u3046\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Karena ada penemuan baru meski salah tujuan dan ia tidak akan membenci perjalanan berapa kali pun salah jalan.)</em></li>\n            <li>3\u3000<u><ruby>\u4eca<rt>\u3053\u3093</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u304b\u3089<ruby>\u9053<rt>\u307f\u3061</rt></ruby>\u3092<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3048\u306a\u3044\u3088\u3046\u306b</u>\u3001\u3082\u3063\u3068<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u3066\u304b\u3089<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092\u3059\u308b\u3060\u308d\u3046\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u4eca<rt>\u3053\u3093</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\u304b\u3089<ruby>\u9053<rt>\u307f\u3061</rt></ruby>\u3092<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3048\u306a\u3044\u3088\u3046\u306b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"agar lain kali tidak salah jalan, akan lebih banyak mencari tahu\".</em></li>\n            <li>4\u3000<u><ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u3088\u308a\u3082<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u304c<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u304f\u306a\u308b\u3088\u3046\u306b\u3001<ruby>\u6642<rt>\u3058</rt></ruby><ruby>\u9593<rt>\u304b\u3093</rt></ruby>\u306b<ruby>\u6ce8<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3057\u3066<ruby>\u65c5<rt>\u305f\u3073</rt></ruby>\u3092\u3059\u308b\u3060\u308d\u3046</u>\u3002\uff08\u00d7\uff09<br><ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u90e8<rt>\u3076</rt></ruby><ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Seluruh pernyataan ini tidak disebutkan di dalam teks.</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): \u2460 2\u3000\u2461 3\u3000\u2462 2</strong></p>\n        </div>\n      </div>\n\n      <!-- Chuubun (2) -->\n      <div class=\"practice-item\" id=\"chuubun-2\">\n        <h5>\uff082\uff09</h5>\n        <div class=\"reading-passage\">\n          <p><ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u8cb7\u3044\u7269\u306b\u51fa\u304b\u3051\u305f\u3068\u304d\u306e\u3053\u3068\u3060\u3002\u304a\u5e97\u306b\u5165\u308b\u3068\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u5f62\u3092\u3057\u305f\u7269\u304c\u305f\u304f\u3055\u3093\u304b\u3056\u3063\u3066\u3042\u3063\u305f\u3002\u305d\u308c\u3092\u898b\u305f<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u306f\u300c<u>\u3044\u3044\u304a\u5e97\u3060\u306d</u>\u300d\u3068\u8a00\u3063\u305f\u3002\u305d\u3057\u3066\u3001\u300c<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u5f62\u306e\u3082\u306e\u3092\u7f6e\u304f\u3068\u3001\u5546\u54c1\u304c\u58f2\u308c\u308b\u3088\u3046\u306b\u306a\u308b\u3093\u3060\u3088\u3002\u300d\u3068\u6559\u3048\u3066\u304f\u308c\u305f\u3002</p>\n          <p>\u6614\u304b\u3089\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306f\u5bb6\u306e\u91ce\u83dc\u3084\u304a\u7c73\u3092\u98df\u3079\u308b\u866b\u306a\u3069\u3092<ruby>\u6355<rt>\u3064\u304b</rt></ruby>\u307e\u3048\u3066\u304f\u308c\u308b\u3044\u3044\u52d5\u7269\u3060\u3068\u8a00\u308f\u308c\u3066\u304d\u305f\u3002\u305d\u308c\u3067\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092<ruby>\u98fc<rt>\u304b</rt></ruby>\u3063\u3066\u3044\u306a\u3044\u5bb6\u3067\u3082\u5165\u308a\u53e3\u306a\u3069\u306b<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u5f62\u306e\u3082\u306e\u3092\u304b\u3056\u308b\u3088\u3046\u306b\u306a\u3063\u305f\u3089\u3057\u3044\u3002\u7279\u306b\u304a\u5e97\u3092\u7d4c\u55b6\u3057\u3066\u3044\u308b\u4eba\u306f\u3001\u5546\u58f2\u304c\u6210\u529f\u3059\u308b\u3088\u3046\u306b\u3068\u9858\u3063\u3066\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092\u304b\u3056\u308b\u3068\u3044\u3046\u3002\u516b\u767e\u5c4b\u3092\u7d4c\u55b6\u3059\u308b<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u3082\u3001\u5bb6\u306e\u305f\u3093\u3059\u306e\u4e0a\u306b<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092\u7f6e\u3044\u3066\u3044\u3066\u3001\u300c\u3046\u3061\u306e\u516b\u767e\u5c4b\u304c\u3046\u307e\u304f\u3044\u304f\u3088\u3046\u306b\u300d\u3068\u9858\u3063\u3066\u3044\u308b\u305d\u3046\u3060\u3002</p>\n          <p><ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u306e\u8a71\u3092\u805e\u3044\u3066\u304b\u3089\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092\u898b\u308b\u305f\u3073\u3001\u79c1\u3082<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304b\u3089\u5b88\u3089\u308c\u3066\u3044\u308b\u3088\u3046\u306b\u611f\u3058\u308b\u3002\u3057\u304b\u3057\u3001\u672c\u5f53\u306b\u305d\u306e\u3088\u3046\u306a\u52b9\u679c\u304c\u3042\u308b\u304b\u306f\u308f\u304b\u3089\u306a\u3044\u3002<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c\u306a\u3093\u3067\u3082\u52a9\u3051\u3066\u304f\u308c\u308b\u308f\u3051\u3067\u306f\u306a\u3044\u3057\u3001\u81ea\u5206\u3067\u52aa\u529b\u3059\u308b\u3053\u3068\u3082\u5fc5\u8981\u3060\u3068\u601d\u3046\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p>Ini terjadi ketika saya pergi berbelanja bersama nenek. Begitu masuk ke sebuah toko, di sana terpajang banyak benda berbentuk kucing. Melihat hal itu, nenek berkata, \"<u>Toko yang bagus ya</u>.\" Lalu beliau memberi tahu saya, \"Kalau menaruh benda berbentuk kucing, barang dagangan akan menjadi laris terjual, lho.\"</p>\n          <p>Sejak zaman dahulu, kucing dikatakan sebagai hewan baik yang menangkap serangga/hama pemakan sayuran atau beras di rumah. Karena itu, konon rumah yang tidak memelihara kucing pun menjadi ikut memajang benda berbentuk kucing di pintu masuk dan tempat lainnya. Terutama orang yang mengelola toko, katanya memajang kucing dengan harapan usahanya sukses. Nenek saya yang mengelola toko sayur dan buah pun menaruh patung kucing di atas lemari laci di rumah, dan katanya beliau berdoa, \"Semoga toko sayur kita berjalan lancar.\"</p>\n          <p>Sejak mendengar cerita nenek, setiap kali melihat kucing, saya pun merasa seakan-akan dilindungi oleh kucing. Akan tetapi, saya tidak tahu apakah benar-benar ada efek seperti itu. Kucing bukan berarti akan membantu dalam segala hal, dan menurut saya berusaha sendiri juga tetap diperlukan.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304c<u>\u3044\u3044\u304a\u5e97\u3060\u306d</u>\u3068\u8a00\u3063\u305f\u3068\u3042\u308b\u304c\u3001\u3069\u3046\u3057\u3066\u304b\u3002<br>\n            <em>Terdapat kalimat bahwa nenek berkata <u>\"Toko yang bagus ya\"</u>, mengapakah demikian?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u5e97\u54e1\u3055\u3093\u304c<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092<ruby>\u98fc<rt>\u304b</rt></ruby>\u3063\u3066\u3044\u305f\u304b\u3089\u3002<br><em>Karena pegawai tokonya memelihara kucing.</em></li>\n            <li><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u5f62\u306e\u5546\u54c1\u304c\u58f2\u3063\u3066\u3044\u305f\u304b\u3089\u3002<br><em>Karena barang dagangan berbentuk kucing dijual di sana.</em></li>\n            <li>\u5546\u54c1\u304c\u305f\u304f\u3055\u3093\u58f2\u308c\u305f\u304b\u3089\u3002<br><em>Karena banyak barang dagangan yang terjual.</em></li>\n            <li><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u5f62\u3092\u3057\u305f\u3082\u306e\u304c\u304b\u3056\u3063\u3066\u3042\u3063\u305f\u304b\u3089\u3002<br><em>Karena di sana terpajang benda-benda berbentuk kucing.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>2</strong>\u3000<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304c<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e\u7f6e\u7269\u3092\u30bf\u30f3\u30b9\u306e\u4e0a\u306b\u7f6e\u304f\u306e\u306f\u306a\u305c\u304b\u3002<br>\n            <em>Mengapa nenek menaruh pajangan kucing di atas lemari laci?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u91ce\u83dc\u3084\u304a\u7c73\u3092\u305f\u304f\u3055\u3093\u98df\u3079\u305f\u3044\u304b\u3089\u3002<br><em>Karena ingin makan banyak sayur dan beras.</em></li>\n            <li><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e\u866b\u3092<ruby>\u6355<rt>\u3064\u304b</rt></ruby>\u307e\u3048\u3066\u307b\u3057\u3044\u304b\u3089\u3002<br><em>Karena ingin kucing menangkap banyak serangga/hama.</em></li>\n            <li>\u5546\u58f2\u304c\u3046\u307e\u304f\u3044\u3063\u3066\u307b\u3057\u3044\u304b\u3089\u3002<br><em>Karena berharap usahanya/dagangannya berjalan lancar.</em></li>\n            <li>\u5fc5\u305a\u5e97\u306e\u7d4c\u55b6\u304c\u6210\u529f\u3059\u308b\u304b\u3089\u3002<br><em>Karena pengelolaan tokonya pasti akan berhasil.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>3</strong>\u3000\u300c\u79c1\u300d\u306f<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092\u304b\u3056\u308b\u3053\u3068\u306b\u3064\u3044\u3066\u3001\u3069\u3046\u601d\u3063\u3066\u3044\u308b\u304b\u3002<br>\n            <em>Bagaimana pendapat \"saya\" mengenai memajang (benda berbentuk) kucing?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u52b9\u679c\u306f\u306a\u3044\u304c\u3001\u5fc3\u3092\u843d\u3061\u7740\u304b\u305b\u308b\u305f\u3081\u306b\u304b\u3056\u308a\u305f\u3044\u3002<br><em>Meskipun tidak ada efeknya, ingin memajangnya untuk menenangkan hati.</em></li>\n            <li><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3082\u52aa\u529b\u3057\u3066\u3044\u308b\u306e\u3067\u3001\u81ea\u5206\u3082\u304c\u3093\u3070\u308d\u3046\u3068\u3044\u3046\u6c17\u6301\u3061\u306b\u306a\u308b\u3002<br><em>Karena kucing juga berusaha, diri sendiri pun jadi bersemangat untuk berjuang.</em></li>\n            <li>\u52b9\u679c\u304c\u3042\u308b\u304b\u308f\u304b\u3089\u306a\u3044\u304c\u3001\u5b88\u3089\u308c\u3066\u3044\u308b\u3088\u3046\u306a\u6c17\u6301\u3061\u306b\u306a\u308b\u3002<br><em>Meskipun tidak tahu apakah ada efeknya, merasa seperti sedang dilindungi.</em></li>\n            <li>\u3060\u3044\u305f\u3044\u306f<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c\u5b88\u3063\u3066\u304f\u308c\u308b\u3088\u3046\u306b\u306a\u308b\u306e\u3067\u3001\u5b89\u5fc3\u3057\u3066\u3044\u308b\u3002<br><em>Karena sebagian besar akan dilindungi oleh kucing, merasa tenang/lega.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n\n          <p><strong>1\u3000<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304c<u>\u3044\u3044\u304a<ruby>\u5e97<rt>\u307f\u305b</rt></ruby>\u3060\u306d</u>\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u305f\u3068\u3042\u308b\u304c\u3001\u3069\u3046\u3057\u3066\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u5e97<rt>\u3066\u3093</rt></ruby><ruby>\u54e1<rt>\u3044\u3093</rt></ruby>\u3055\u3093\u304c<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092<ruby>\u98fc<rt>\u304b</rt></ruby>\u3063\u3066\u3044\u305f\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>2\u3000<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u306e<ruby>\u5546<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u54c1<rt>\u3072\u3093</rt></ruby>\u304c<ruby>\u58f2<rt>\u3046</rt></ruby>\u3063\u3066\u3044\u305f\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>3\u3000<ruby>\u5546<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u54c1<rt>\u3072\u3093</rt></ruby>\u304c\u305f\u304f\u3055\u3093<ruby>\u58f2<rt>\u3046</rt></ruby>\u308c\u305f\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li><strong>4\u3000<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u3092\u3057\u305f\u3082\u306e\u304c\u304b\u3056\u3063\u3066\u3042\u3063\u305f\u304b\u3089\u3002\uff08\u3007\uff09</strong></li>\n          </ul>\n          <p>\n            \u203b\u300c\u304a<ruby>\u5e97<rt>\u307f\u305b</rt></ruby>\u306b<ruby>\u5165<rt>\u306f\u3044</rt></ruby>\u308b\u3068\u3001<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e<ruby>\u5f62<rt>\u304b\u305f\u3061</rt></ruby>\u3092\u3057\u305f<ruby>\u7269<rt>\u3082\u306e</rt></ruby>\u304c\u305f\u304f\u3055\u3093\u304b\u3056\u3063\u3066\u3042\u3063\u305f\u3002\u300d\u3053\u3068\u304c<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u3060\u304b\u30894\u304c<ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3002<br>\n            <em>Catatan: Karena alasannya adalah \"begitu masuk ke toko, di sana terpajang banyak benda berbentuk kucing\", maka pilihan <strong>4</strong> adalah jawaban yang benar.</em>\n          </p>\n\n          <p><strong>2\u3000<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304c<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306e<ruby>\u7f6e<rt>\u304a\u304d</rt></ruby><ruby>\u7269<rt>\u3082\u306e</rt></ruby>\u3092\u30bf\u30f3\u30b9\u306e<ruby>\u4e0a<rt>\u3046\u3048</rt></ruby>\u306b<ruby>\u7f6e<rt>\u304a</rt></ruby>\u304f\u306e\u306f\u306a\u305c\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u91ce<rt>\u3084</rt></ruby><ruby>\u83dc<rt>\u3055\u3044</rt></ruby>\u3084\u304a<ruby>\u7c73<rt>\u3053\u3081</rt></ruby>\u3092\u305f\u304f\u3055\u3093<ruby>\u98df<rt>\u305f</rt></ruby>\u3079\u305f\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>2\u3000<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u306b\u305f\u304f\u3055\u3093\u306e<ruby>\u866b<rt>\u3080\u3057</rt></ruby>\u3092<ruby>\u6355<rt>\u3064\u304b</rt></ruby>\u307e\u3048\u3066\u307b\u3057\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li><strong>3\u3000<ruby>\u5546<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u58f2<rt>\u3070\u3044</rt></ruby>\u304c\u3046\u307e\u304f\u3044\u3063\u3066\u307b\u3057\u3044\u304b\u3089\u3002\uff08\u3007\uff09</strong></li>\n            <li>4\u3000<ruby>\u5fc5<rt>\u304b\u306a\u3089</rt></ruby>\u305a<ruby>\u5e97<rt>\u307f\u305b</rt></ruby>\u306e<ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u55b6<rt>\u3048\u3044</rt></ruby>\u304c<ruby>\u6210<rt>\u305b\u3044</rt></ruby><ruby>\u529f<rt>\u3053\u3046</rt></ruby>\u3059\u308b\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n          </ul>\n          <p>\n            \u203b\u300c<ruby>\u516b<rt>\u3084</rt></ruby><ruby>\u767e<rt>\u304a</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u3092<ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u55b6<rt>\u3048\u3044</rt></ruby>\u3059\u308b<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u3082\u3001<ruby>\u5bb6<rt>\u3044\u3048</rt></ruby>\u306e\u305f\u3093\u3059\u306e<ruby>\u4e0a<rt>\u3046\u3048</rt></ruby>\u306b<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092<ruby>\u7f6e<rt>\u304a</rt></ruby>\u3044\u3066\u3044\u3066\u3001\u300c\u3046\u3061\u306e<ruby>\u516b<rt>\u3084</rt></ruby><ruby>\u767e<rt>\u304a</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u304c\u3046\u307e\u304f\u3044\u304f\u3088\u3046\u306b\u300d\u3068<ruby>\u9858<rt>\u306d\u304c</rt></ruby>\u3063\u3066\u3044\u308b\u300d\u3068\u3042\u308b\u306e\u3067\u30013\u304c<ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3002<br>\n            <em>Catatan: Karena tertulis \"Nenek yang mengelola toko sayur juga menaruh kucing di atas lemari laci di rumah dan berdoa 'semoga toko sayur kita berjalan lancar'\", maka pilihan <strong>3</strong> adalah jawaban yang benar.</em>\n          </p>\n\n          <p><strong>3\u3000\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u300d\u306f<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3092\u304b\u3056\u308b\u3053\u3068\u306b\u3064\u3044\u3066\u3001\u3069\u3046<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3063\u3066\u3044\u308b\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<u><ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby>\u306f\u306a\u3044</u>\u304c\u3001<ruby>\u5fc3<rt>\u3053\u3053\u308d</rt></ruby>\u3092<ruby>\u843d<rt>\u304a</rt></ruby>\u3061<ruby>\u7740<rt>\u3064</rt></ruby>\u304b\u305b\u308b\u305f\u3081\u306b\u304b\u3056\u308a\u305f\u3044\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby>\u306f\u306a\u3044\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"tidak ada efeknya\" (melainkan \"tidak tahu apakah ada efeknya\").</em></li>\n            <li>2\u3000<u><ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u3082<ruby>\u52aa<rt>\u3069</rt></ruby><ruby>\u529b<rt>\u308a\u3087\u304f</rt></ruby>\u3057\u3066\u3044\u308b\u306e\u3067\u3001<ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u5206<rt>\u3076\u3093</rt></ruby>\u3082\u304c\u3093\u3070\u308d\u3046\u3068\u3044\u3046<ruby>\u6c17<rt>\u304d</rt></ruby><ruby>\u6301<rt>\u3082</rt></ruby>\u3061\u306b\u306a\u308b</u>\u3002\uff08\u00d7\uff09<br><ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u90e8<rt>\u3076</rt></ruby><ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Seluruh bagian ini tidak disebutkan di dalam teks.</em></li>\n            <li><strong>3\u3000<ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby>\u304c\u3042\u308b\u304b\u308f\u304b\u3089\u306a\u3044\u304c\u3001<ruby>\u5b88<rt>\u307e\u3082</rt></ruby>\u3089\u308c\u3066\u3044\u308b\u3088\u3046\u306a<ruby>\u6c17<rt>\u304d</rt></ruby><ruby>\u6301<rt>\u3082</rt></ruby>\u3061\u306b\u306a\u308b\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar!</em></li>\n            <li>4\u3000<u>\u3060\u3044\u305f\u3044\u306f<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c<ruby>\u5b88<rt>\u307e\u3082</rt></ruby>\u3063\u3066\u304f\u308c\u308b\u3088\u3046\u306b\u306a\u308b</u>\u306e\u3067\u3001<ruby>\u5b89<rt>\u3042\u3093</rt></ruby><ruby>\u5fc3<rt>\u3057\u3093</rt></ruby>\u3057\u3066\u3044\u308b\u3002\uff08\u00d7\uff09<br>\u300c\u3060\u3044\u305f\u3044\u306f<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c<ruby>\u5b88<rt>\u307e\u3082</rt></ruby>\u3063\u3066\u304f\u308c\u308b\u3088\u3046\u306b\u306a\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"sebagian besar akan dilindungi oleh kucing\".</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): \u2460 4\u3000\u2461 3\u3000\u2462 3</strong></p>\n        </div>\n      </div>\n    </div>\n\n    <!-- ===== MASALAH 6: CHOUBUN ===== -->\n    <div class=\"reading-section\" id=\"reading-choubun\">\n      <h4>6. Pemahaman Isi \u00b7 Teks Panjang (<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09)</h4>\n\n      <div class=\"info-box\">\n        <p>\n          <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>6\u3067\u306f\u3001<ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff08700<ruby>\u5b57<rt>\u3058</rt></ruby><ruby>\u7a0b<rt>\u3066\u3044</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\uff09\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u307e\u3059\u3002<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u66f8<rt>\u304b</rt></ruby>\u3044\u305f<ruby>\u4eba<rt>\u3072\u3068</rt></ruby>\u306e<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u3001<ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u56e0<rt>\u3044\u3093</rt></ruby>\u3084<ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u7531<rt>\u3086\u3046</rt></ruby>\u306b\u3064\u3044\u3066\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\uff08<ruby>\u9577<rt>\u3061\u3087\u3046</rt></ruby><ruby>\u6587<rt>\u3076\u3093</rt></ruby>\uff09\u306f<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c1\u3064\u3042\u308a\u30014\u3064\u306e<ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<br>\n          <em>Pada Bagian 6 (Mondai 6), Anda akan membaca teks panjang (sekitar 700 huruf). Soal yang keluar menanyakan pemikiran penulis teks, serta sebab atau alasan. Pemahaman Isi (Teks Panjang) memiliki 1 bacaan utama dengan 4 pertanyaan.</em>\n        </p>\n        <p>\n          <strong>\u554f\u984c6</strong>\u3000\u3064\u304e\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092\u8aad\u3093\u3067\u3001\u8cea\u554f\u306b\u7b54\u3048\u306a\u3055\u3044\u3002\u7b54\u3048\u306f\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br>\n          <em><strong>Soal 6:</strong> Bacalah teks berikut ini, lalu jawablah pertanyaannya. Pilihlah satu jawaban yang paling tepat dari pilihan 1, 2, 3, atau 4.</em>\n        </p>\n      </div>\n\n      <div class=\"practice-item\" id=\"choubun-1\">\n        <div class=\"reading-passage\">\n          <p>2020\u5e74\u304b\u3089\u3001\u5168\u56fd\u306e\u5c0f\u5b66\u6821\u3067\u30d1\u30bd\u30b3\u30f3\u306e\u4f7f\u3044\u65b9\u306e<ruby>\u57fa<rt>\u304d</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby>\u3092\u6559\u3048\u308b\u3053\u3068\u306b\u306a\u3063\u305f\u3002\u305d\u3057\u3066\u79c1\u3082\u3001\u6765\u5e74\u306e\u6625\u304b\u3089\u30014\u5e74\u751f\u306b\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3092\u3059\u308b\u3053\u3068\u306b\u306a\u3063\u305f\u3002</p>\n          <p>\u30d1\u30bd\u30b3\u30f3\u306b\u3064\u3044\u3066\u52c9\u5f37\u3059\u308b\u3053\u3068\u306f\u3001\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u793e\u4f1a\u3092\u751f\u304d\u308b\u305f\u3081\u306b\u5fc5\u8981\u306a\u300c\u60c5\u5831\u3092\u8abf\u3079\u308b\u529b\u300d\u3092\u8eab\u306b\u3064\u3051\u3089\u308c\u308b\u3068\u3044\u3046\u3002\u307e\u305f\u3001<ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3063\u305f\u308a\u60a9\u3093\u3060\u308a\u3057\u305f\u3068\u304d\u3001\u6b63\u3057\u3044\u60c5\u5831\u3092<ruby>\u63a2<rt>\u3055\u304c</rt></ruby>\u3057\u305f\u308a\u3001\u6b63\u3057\u3044\u65b9\u3092\u9078\u3093\u3060\u308a\u3059\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3088\u3046\u306b\u306a\u308b\u3060\u308d\u3046\u3002</p>\n          <p>\u300c\u30b2\u30fc\u30e0\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u304b\u3089\u300d\u3068\u3044\u3046\u7406\u7531\u3067\u5148\u751f\u306b\u9078\u3070\u308c\u305f\u304c\u3001\u5b9f\u306f\u3001\u79c1\u304c\u597d\u304d\u306a\u306e\u306f<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby>\u96fb\u8a71\u306e\u30b2\u30fc\u30e0\u3060\u3002\u30d1\u30bd\u30b3\u30f3\u306f\u3042\u307e\u308a\u4f7f\u308f\u306a\u3044\u3057\u3001\u3069\u306e\u3088\u3046\u306b\u6559\u3048\u308c\u3070\u3044\u3044\u306e\u304b\u308f\u304b\u3089\u306a\u3044\u306e\u3067<u>\u3068\u3066\u3082\u4e0d\u5b89\u3060</u>\u3002\u65e9\u901f\u3001\u6559\u3048\u65b9\u306b\u3064\u3044\u3066\u8abf\u3079\u308b\u3053\u3068\u306b\u3057\u305f\u3002</p>\n          <p>\u307e\u305a\u3001\u5b50\u3069\u3082\u306b\u30d1\u30bd\u30b3\u30f3\u306e\u4f7f\u3044\u65b9\u3092\u6559\u3048\u308b\u3068\u304d\u306b\u5927\u5207\u306a\u3053\u3068\u306f\u300c\u30d1\u30bd\u30b3\u30f3\u3092\u597d\u304d\u306b\u306a\u3063\u3066\u3082\u3089\u3046\u3053\u3068\u300d\u3060\u305d\u3046\u3060\u3002\u3082\u3046\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3092\u59cb\u3081\u3066\u3044\u308b\u5b66\u6821\u304c\u3001<ruby>\u5b9f<rt>\u3058\u3063</rt></ruby><ruby>\u969b<rt>\u3055\u3044</rt></ruby>\u306b\u4f7f\u3063\u3066\u3044\u308b\u6709\u540d\u306a\u30b5\u30a4\u30c8\u304c\u4e8c\u3064\u3042\u308b\u3002</p>\n          <p>\u4e00\u3064\u76ee\u306f\u3001\u30d1\u30bd\u30b3\u30f3\u3092\u4f7f\u3063\u3066\u7d75\u3092\u304b\u304d\u3001\u305d\u306e\u7d75\u3092\u81ea\u7531\u306b\u52d5\u304b\u3059\u3053\u3068\u304c\u3067\u304d\u308b\u3068\u3044\u3046\u3082\u306e\u3060\u3002\u4f7f\u3044\u65b9\u306f\u7c21\u5358\u3060\u304c\u3001\u306a\u304b\u306a\u304b\u81ea\u7531\u306b\u52d5\u304b\u3059\u3053\u3068\u304c\u3067\u304d\u305a\u306b\u82e6\u52b4\u3057\u305f\u3002\u4e8c\u3064\u76ee\u306f\u3001\u30b2\u30fc\u30e0\u3084\u30af\u30a4\u30ba\u3092\u3057\u306a\u304c\u3089\u3001\u30d1\u30bd\u30b3\u30f3\u306e\u4f7f\u3044\u65b9\u3092\u52c9\u5f37\u3059\u308b\u3068\u3044\u3046\u3082\u306e\u3060\u3002\u30af\u30a4\u30ba\u306f\u6570\u5b66\u306e\u5185\u5bb9\u306e\u3082\u306e\u304c\u591a\u304f\u3001\u5927\u4eba\u306e\u79c1\u3067\u3082\u96e3\u3057\u3044\u30ec\u30d9\u30eb\u306e\u3082\u306e\u3082\u3042\u3063\u305f\u3002\u3069\u3061\u3089\u306b\u3057\u3066\u3082\u3001<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u306e\u524d\u306b\u3001\u5148\u751f\u304c\u4f7f\u3044\u65b9\u3092\u3088\u304f\u7406\u89e3\u3059\u308b\u5fc5\u8981\u304c\u3042\u308a\u305d\u3046\u3060\u3002</p>\n          <p>\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u6271<rt>\u3042\u3064\u304b</rt></ruby>\u3044\u306b<ruby>\u6163<rt>\u306a</rt></ruby>\u308c\u308b\u3053\u3068\u3082\u3082\u3061\u308d\u3093\u5fc5\u8981\u3060\u304c\u3001\u79c1\u3082\u751f\u5f92\u5074\u306b\u306a\u3063\u3066\u5b66\u3076\u7d4c\u9a13\u304c\u5fc5\u8981\u3060\u3068\u8003\u3048\u305f\u3002<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u304c\u59cb\u307e\u308b\u524d\u306b\u3001\u79c1\u3082\u30d1\u30bd\u30b3\u30f3\u6559\u5ba4\u306b\u901a\u3063\u3066\u3001\u6559\u3048\u3066\u3082\u3089\u3046\u7d4c\u9a13\u3092\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3068\u601d\u3046\u3002</p>\n        </div>\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks:</h4>\n          <p>Mulai tahun 2020, ditetapkan bahwa dasar-dasar cara menggunakan komputer akan diajarkan di sekolah dasar di seluruh negeri. Lalu saya pun, mulai musim semi tahun depan, ditugaskan untuk mengajar pelajaran komputer kepada siswa kelas 4.</p>\n          <p>Konon, belajar tentang komputer dapat membekali anak-anak dengan \"kemampuan mencari informasi\" yang diperlukan untuk hidup di masyarakat internet. Selain itu, ketika merasa bimbang atau mengalami kebingungan, mereka juga akan mampu mencari informasi yang benar maupun memilih pilihan yang tepat.</p>\n          <p>Saya terpilih menjadi guru dengan alasan \"karena pandai bermain game\", padahal sebenarnya yang saya sukai adalah game ponsel. Saya jarang menggunakan komputer, dan karena tidak tahu bagaimana cara mengajarkannya, saya <u>merasa sangat cemas</u>. Saya pun segera mencari tahu tentang cara mengajarnya.</p>\n          <p>Pertama-tama, katanya hal yang penting ketika mengajari anak-anak cara menggunakan komputer adalah \"membuat mereka menyukai komputer\". Ada dua situs terkenal yang benar-benar sedang digunakan oleh sekolah-sekolah yang sudah memulai pelajaran komputer.</p>\n          <p>Situs yang pertama memungkinkan pengguna menggambar memakai komputer dan menggerakkan gambar tersebut secara bebas. Cara penggunaannya mudah, tetapi saya kesulitan karena tidak kunjung bisa menggerakkannya dengan bebas. Situs yang kedua adalah belajar cara menggunakan komputer sambil bermain game dan kuis. Kuisnya banyak yang berisi materi matematika, dan ada juga yang tingkat kesulitannya sulit bahkan bagi saya yang sudah dewasa. Bagaimanapun juga, tampaknya sebelum pelajaran dimulai, guru perlu memahami cara penggunaannya dengan baik.</p>\n          <p>Tentu saja terbiasa mengoperasikan komputer itu perlu, tetapi saya berpikir bahwa saya juga membutuhkan pengalaman belajar dari posisi sebagai murid. Sebelum pelajaran dimulai, saya rasa saya juga harus mengikuti kursus komputer untuk merasakan pengalaman diajari.</p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u3053\u306e\u6587\u7ae0\u3067\u306f\u3001\u5b50\u3069\u3082\u306b\u30d1\u30bd\u30b3\u30f3\u306e\u4f7f\u3044\u65b9\u3092\u6559\u3048\u308b\u3053\u3068\u306b\u306f\u3069\u3093\u306a\u52b9\u679c\u304c\u3042\u308b\u3068\u8a00\u3063\u3066\u3044\u308b\u304b\u3002<br>\n            <em>Dalam teks ini, manfaat apa yang dikatakan dapat diperoleh dari mengajari anak-anak cara menggunakan komputer?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u5b50\u3069\u3082\u305f\u3061\u304c\u3001\u30b2\u30fc\u30e0\u3092\u3082\u3063\u3068\u697d\u3057\u3080\u3053\u3068\u304c\u3067\u304d\u308b\u3002<br><em>Anak-anak dapat lebih menikmati game.</em></li>\n            <li>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u793e\u4f1a\u3092\u8abf\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u308b\u3002<br><em>Dapat meneliti/mencari tahu tentang masyarakat internet.</em></li>\n            <li><ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u3001<ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3063\u305f\u308a\u60a9\u3093\u3060\u308a\u3057\u306a\u304f\u306a\u308b\u3002<br><em>Di masa depan, tidak akan lagi merasa bimbang maupun bingung.</em></li>\n            <li>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u793e\u4f1a\u3067\u5fc5\u8981\u306a\u529b\u3092\u8eab\u306b\u3064\u3051\u3089\u308c\u308b\u3002<br><em>Dapat menguasai kemampuan yang diperlukan di dalam masyarakat internet.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>2</strong>\u3000<u>\u3068\u3066\u3082\u4e0d\u5b89\u3060</u>\u3068\u3042\u308b\u304c\u3001\u4f55\u304c\u4e0d\u5b89\u306a\u306e\u304b\u3002<br>\n            <em>Terdapat ungkapan <u>\"merasa sangat cemas\"</u>, apakah yang dicemaskan?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li><ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby>\u3084\u30d1\u30bd\u30b3\u30f3\u306e\u30b2\u30fc\u30e0\u306e\u6559\u3048\u65b9\u304c\u308f\u304b\u3089\u306a\u3044\u304b\u3089\u3002<br><em>Karena tidak tahu cara mengajarkan game ponsel maupun komputer.</em></li>\n            <li><ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby>\u3084\u30d1\u30bd\u30b3\u30f3\u306e\u30b2\u30fc\u30e0\u304c\u3088\u304f\u308f\u304b\u3089\u306a\u3044\u304b\u3089\u3002<br><em>Karena tidak begitu memahami game ponsel maupun komputer.</em></li>\n            <li>\u30b2\u30fc\u30e0\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u3068\u3001\u30d1\u30bd\u30b3\u30f3\u306e\u4f7f\u3044\u65b9\u3092\u6559\u3048\u308b\u3053\u3068\u306f\u96e3\u3057\u3044\u304b\u3089\u3002<br><em>Karena jika mahir bermain game, sulit untuk mengajarkan cara menggunakan komputer.</em></li>\n            <li>\u30b2\u30fc\u30e0\u306f<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u304c\u3001\u30d1\u30bd\u30b3\u30f3\u306f<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u306f\u306a\u3044\u304b\u3089\u3002<br><em>Karena meskipun mahir bermain game, ia tidak mahir menggunakan komputer.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>3</strong>\u3000\u30b5\u30a4\u30c8\u306b\u3064\u3044\u3066\u3001\u5408\u3063\u3066\u3044\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002<br>\n            <em>Mengenai situs-situs tersebut, manakah pernyataan yang benar?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u7d75\u3092\u304b\u304f\u30b5\u30a4\u30c8\u306f\u3001\u30af\u30a4\u30ba\u3092\u89e3\u304f\u3060\u3051\u306a\u306e\u3067\u7c21\u5358\u3060\u3002<br><em>Situs untuk menggambar mudah karena hanya menyelesaikan kuis saja.</em></li>\n            <li>\u7d75\u3092\u304b\u304f\u30b5\u30a4\u30c8\u306f\u3001\u7d75\u3092\u52d5\u304b\u3059\u306e\u304c\u96e3\u3057\u3044\u3002<br><em>Pada situs untuk menggambar, menggerakkan gambarnya sulit.</em></li>\n            <li>\u30b2\u30fc\u30e0\u3067\u52c9\u5f37\u3059\u308b\u30b5\u30a4\u30c8\u306f\u3001\u6570\u5b66\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3067\u4f7f\u3048\u308b\u3002<br><em>Situs untuk belajar dengan game dapat digunakan dalam pelajaran matematika.</em></li>\n            <li>\u30b2\u30fc\u30e0\u3067\u52c9\u5f37\u3059\u308b\u30b5\u30a4\u30c8\u306f\u3001\u4f7f\u3044\u65b9\u304c\u7c21\u5358\u3060\u3002<br><em>Situs untuk belajar dengan game mudah cara penggunaannya.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>4</strong>\u3000\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3092\u3059\u308b\u524d\u306b\u3001\u300c\u79c1\u300d\u306f\u3069\u3046\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3068\u8003\u3048\u3066\u3044\u308b\u304b\u3002<br>\n            <em>Sebelum mengajar pelajaran komputer, apa yang menurut \"saya\" harus dilakukannya?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>\u751f\u5f92\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u30d1\u30bd\u30b3\u30f3\u6559\u5ba4\u306b\u901a\u3046\u5fc5\u8981\u304c\u3042\u308b\u3002<br><em>Perlu mengikuti kursus komputer bersama-sama dengan para murid.</em></li>\n            <li>\u30d1\u30bd\u30b3\u30f3\u3092\u597d\u304d\u306b\u306a\u3063\u3066\u4f7f\u3044\u65b9\u306b<ruby>\u6163<rt>\u306a</rt></ruby>\u308c\u308b\u5fc5\u8981\u304c\u3042\u308b\u3002<br><em>Perlu menyukai komputer dan membiasakan diri dengan cara penggunaannya.</em></li>\n            <li>\u751f\u5f92\u306e\u6c17\u6301\u3061\u304c\u308f\u304b\u308b\u3088\u3046\u306b\u3001\u6559\u3048\u3066\u3082\u3089\u3046\u3068\u3044\u3046\u7d4c\u9a13\u3092\u3059\u308b\u5fc5\u8981\u304c\u3042\u308b\u3002<br><em>Perlu merasakan pengalaman diajari agar dapat memahami perasaan murid.</em></li>\n            <li>\u30d1\u30bd\u30b3\u30f3\u6559\u5ba4\u306b\u901a\u3063\u3066\u3001\u6559\u3048\u65b9\u3092\u52c9\u5f37\u3059\u308b\u5fc5\u8981\u304c\u3042\u308b\u3002<br><em>Perlu mengikuti kursus komputer untuk mempelajari cara mengajar.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n\n          <p><strong>1\u3000\u3053\u306e<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3067\u306f\u3001<ruby>\u5b50<rt>\u3053</rt></ruby>\u3069\u3082\u306b\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3044<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048\u308b\u3053\u3068\u306b\u306f\u3069\u3093\u306a<ruby>\u52b9<rt>\u3053\u3046</rt></ruby><ruby>\u679c<rt>\u304b</rt></ruby>\u304c\u3042\u308b\u3068<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u308b\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u5b50<rt>\u3053</rt></ruby>\u3069\u3082\u305f\u3061\u304c\u3001<u>\u30b2\u30fc\u30e0\u3092\u3082\u3063\u3068<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3080\u3053\u3068\u304c\u3067\u304d\u308b</u>\u3002\uff08\u00d7\uff09<br>\u300c\u30b2\u30fc\u30e0\u3092\u3082\u3063\u3068<ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3080\u3053\u3068\u304c\u3067\u304d\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"dapat lebih menikmati game\".</em></li>\n            <li>2\u3000<u>\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8<ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u3092<ruby>\u8abf<rt>\u3057\u3089</rt></ruby>\u3079\u308b\u3053\u3068\u304c\u3067\u304d\u308b</u>\u3002\uff08\u00d7\uff09<br><ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u90e8<rt>\u3076</rt></ruby><ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Seluruh pernyataan ini tidak disebutkan di dalam teks.</em></li>\n            <li>3\u3000<ruby>\u5c06<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u6765<rt>\u3089\u3044</rt></ruby>\u3001<u><ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3063\u305f\u308a<ruby>\u60a9<rt>\u306a\u3084</rt></ruby>\u3093\u3060\u308a\u3057\u306a\u304f\u306a\u308b</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u8ff7<rt>\u307e\u3088</rt></ruby>\u3063\u305f\u308a<ruby>\u60a9<rt>\u306a\u3084</rt></ruby>\u3093\u3060\u308a\u3057\u306a\u304f\u306a\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"tidak akan lagi merasa bimbang maupun bingung\" (melainkan mampu mencari informasi yang benar dan memilih yang tepat ketika bimbang/bingung).</em></li>\n            <li><strong>4\u3000\u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8<ruby>\u793e<rt>\u3057\u3083</rt></ruby><ruby>\u4f1a<rt>\u304b\u3044</rt></ruby>\u3067<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u306a<ruby>\u529b<rt>\u3061\u304b\u3089</rt></ruby>\u3092<ruby>\u8eab<rt>\u307f</rt></ruby>\u306b\u3064\u3051\u3089\u308c\u308b\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Pada paragraf 2 dijelaskan bahwa mereka dapat menguasai \"kemampuan mencari informasi\" yang diperlukan untuk hidup di masyarakat internet.)</em></li>\n          </ul>\n\n          <p><strong>2\u3000<u>\u3068\u3066\u3082<ruby>\u4e0d<rt>\u3075</rt></ruby><ruby>\u5b89<rt>\u3042\u3093</rt></ruby>\u3060</u>\u3068\u3042\u308b\u304c\u3001<ruby>\u4f55<rt>\u306a\u306b</rt></ruby>\u304c<ruby>\u4e0d<rt>\u3075</rt></ruby><ruby>\u5b89<rt>\u3042\u3093</rt></ruby>\u306a\u306e\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby>\u3084\u30d1\u30bd\u30b3\u30f3\u306e\u30b2\u30fc\u30e0\u306e<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c\u308f\u304b\u3089\u306a\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>2\u3000<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby>\u3084\u30d1\u30bd\u30b3\u30f3\u306e\u30b2\u30fc\u30e0\u304c\u3088\u304f\u308f\u304b\u3089\u306a\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li>3\u3000\u30b2\u30fc\u30e0\u304c<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u3068\u3001\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3044<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048\u308b\u3053\u3068\u306f<ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u3044\u304b\u3089\u3002\uff08\u00d7\uff09</li>\n            <li><strong>4\u3000\u30b2\u30fc\u30e0\u306f<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3060\u304c\u3001\u30d1\u30bd\u30b3\u30f3\u306f<ruby>\u5f97<rt>\u3068\u304f</rt></ruby><ruby>\u610f<rt>\u3044</rt></ruby>\u3067\u306f\u306a\u3044\u304b\u3089\u3002\uff08\u3007\uff09</strong></li>\n          </ul>\n          <p>\n            \u203b\u300c\u30d1\u30bd\u30b3\u30f3\u306f\u3042\u307e\u308a<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u308f\u306a\u3044\u3057\u3001\u3069\u306e\u3088\u3046\u306b<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048\u308c\u3070\u3044\u3044\u306e\u304b\u308f\u304b\u3089\u306a\u3044\u300d\u3068\u3042\u308b\u306e\u3067\u30014\u304c<ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u89e3<rt>\u304b\u3044</rt></ruby>\u3002<br>\n            <em>Catatan: Karena tertulis \"saya jarang menggunakan komputer dan tidak tahu bagaimana cara mengajarkannya\" (padahal dipilih karena pandai bermain game ponsel), maka pilihan <strong>4</strong> adalah jawaban yang benar.</em>\n          </p>\n\n          <p><strong>3\u3000\u30b5\u30a4\u30c8\u306b\u3064\u3044\u3066\u3001<ruby>\u5408<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<ruby>\u7d75<rt>\u3048</rt></ruby>\u3092\u304b\u304f\u30b5\u30a4\u30c8\u306f\u3001<u>\u30af\u30a4\u30ba\u3092<ruby>\u89e3<rt>\u3068</rt></ruby>\u304f</u>\u3060\u3051\u306a\u306e\u3067<ruby>\u7c21<rt>\u304b\u3093</rt></ruby><ruby>\u5358<rt>\u305f\u3093</rt></ruby>\u3060\u3002\uff08\u00d7\uff09<br>\u300c\u30af\u30a4\u30ba\u3092<ruby>\u89e3<rt>\u3068</rt></ruby>\u304f\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan situs menggambar adalah untuk \"menyelesaikan kuis\".</em></li>\n            <li><strong>2\u3000<ruby>\u7d75<rt>\u3048</rt></ruby>\u3092\u304b\u304f\u30b5\u30a4\u30c8\u306f\u3001<ruby>\u7d75<rt>\u3048</rt></ruby>\u3092<ruby>\u52d5<rt>\u3046\u3054</rt></ruby>\u304b\u3059\u306e\u304c<ruby>\u96e3<rt>\u3080\u305a\u304b</rt></ruby>\u3057\u3044\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Pada paragraf 5 tertulis \"\u306a\u304b\u306a\u304b\u81ea\u7531\u306b\u52d5\u304b\u3059\u3053\u3068\u304c\u3067\u304d\u305a\u306b\u82e6\u52b4\u3057\u305f\" / kesulitan menggerakkannya secara bebas.)</em></li>\n            <li>3\u3000\u30b2\u30fc\u30e0\u3067<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3059\u308b\u30b5\u30a4\u30c8\u306f\u3001<u><ruby>\u6570<rt>\u3059\u3046</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby>\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3067<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3048\u308b</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u6570<rt>\u3059\u3046</rt></ruby><ruby>\u5b66<rt>\u304c\u304f</rt></ruby>\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3067<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3048\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"dapat digunakan dalam pelajaran matematika\" (hanya dikatakan kuisnya banyak yang berisi materi matematika).</em></li>\n            <li>4\u3000\u30b2\u30fc\u30e0\u3067<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3059\u308b\u30b5\u30a4\u30c8\u306f\u3001<u><ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3044<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u7c21<rt>\u304b\u3093</rt></ruby><ruby>\u5358<rt>\u305f\u3093</rt></ruby>\u3060</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3044<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u304c<ruby>\u7c21<rt>\u304b\u3093</rt></ruby><ruby>\u5358<rt>\u305f\u3093</rt></ruby>\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan situs kedua ini \"cara penggunaannya mudah\" (kalimat itu merujuk pada situs pertama).</em></li>\n          </ul>\n\n          <p><strong>4\u3000\u30d1\u30bd\u30b3\u30f3\u306e<ruby>\u6388<rt>\u3058\u3085</rt></ruby><ruby>\u696d<rt>\u304e\u3087\u3046</rt></ruby>\u3092\u3059\u308b<ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b\u3001\u300c<ruby>\u79c1<rt>\u308f\u305f\u3057</rt></ruby>\u300d\u306f\u3069\u3046\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3068<ruby>\u8003<rt>\u304b\u3093\u304c</rt></ruby>\u3048\u3066\u3044\u308b\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<u><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u5f92<rt>\u3068</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby></u>\u306b\u30d1\u30bd\u30b3\u30f3<ruby>\u6559<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby>\u306b<ruby>\u901a<rt>\u304b\u3088</rt></ruby>\u3046<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u5f92<rt>\u3068</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"bersama-sama dengan para murid\".</em></li>\n            <li>2\u3000<u>\u30d1\u30bd\u30b3\u30f3\u3092<ruby>\u597d<rt>\u3059</rt></ruby>\u304d\u306b\u306a\u3063\u3066</u><ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3044<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u306b<ruby>\u6163<rt>\u306a</rt></ruby>\u308c\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b\u3002\uff08\u00d7\uff09<br>\u300c\u30d1\u30bd\u30b3\u30f3\u3092<ruby>\u597d<rt>\u3059</rt></ruby>\u304d\u306b\u306a\u3063\u3066\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan bahwa gurunya harus \"menyukai komputer\" (yang harus menyukai komputer adalah anak-anak/murid).</em></li>\n            <li><strong>3\u3000<ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u5f92<rt>\u3068</rt></ruby>\u306e<ruby>\u6c17<rt>\u304d</rt></ruby><ruby>\u6301<rt>\u3082</rt></ruby>\u3061\u304c\u308f\u304b\u308b\u3088\u3046\u306b\u3001<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048\u3066\u3082\u3089\u3046\u3068\u3044\u3046<ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby>\u3092\u3059\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Pada paragraf terakhir penulis berpikir perlunya menjadi pihak murid dan merasakan pengalaman diajari.)</em></li>\n            <li>4\u3000\u30d1\u30bd\u30b3\u30f3<ruby>\u6559<rt>\u304d\u3087\u3046</rt></ruby><ruby>\u5ba4<rt>\u3057\u3064</rt></ruby>\u306b<ruby>\u901a<rt>\u304b\u3088</rt></ruby>\u3063\u3066\u3001<u><ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3059\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b</u>\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u6559<rt>\u304a\u3057</rt></ruby>\u3048<ruby>\u65b9<rt>\u304b\u305f</rt></ruby>\u3092<ruby>\u52c9<rt>\u3079\u3093</rt></ruby><ruby>\u5f37<rt>\u304d\u3087\u3046</rt></ruby>\u3059\u308b<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan datang ke kursus komputer untuk \"mempelajari cara mengajar\".</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): \u2460 4\u3000\u2461 4\u3000\u2462 2\u3000\u2463 3</strong></p>\n        </div>\n      </div>\n    </div>\n\n    <!-- ===== MASALAH 7: JOUHOU KENSAKU ===== -->\n    <div class=\"reading-section\" id=\"reading-info-retrieval\">\n      <h4>7. Pencarian Informasi (<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby><ruby>\u691c<rt>\u3051\u3093</rt></ruby><ruby>\u7d22<rt>\u3055\u304f</rt></ruby>)</h4>\n\n      <div class=\"info-box\">\n        <p>\n          <ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>7\u3067\u306f\u3001\u304a<ruby>\u77e5<rt>\u3057</rt></ruby>\u3089\u305b\u306e<ruby>\u7d19<rt>\u304b\u307f</rt></ruby>\u30fb\u30d1\u30f3\u30d5\u30ec\u30c3\u30c8\u30fb\u3061\u3089\u3057\u30fb\u30dd\u30b9\u30bf\u30fc\u306a\u3069\uff08600<ruby>\u5b57<rt>\u3058</rt></ruby><ruby>\u7a0b<rt>\u3066\u3044</rt></ruby><ruby>\u5ea6<rt>\u3069</rt></ruby>\uff09\u3092<ruby>\u8aad<rt>\u3088</rt></ruby>\u307f\u307e\u3059\u3002\u305d\u3057\u3066\u3001\u305d\u306e<ruby>\u5185<rt>\u306a\u3044</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby>\u306b\u3064\u3044\u3066<ruby>\u7b54<rt>\u3053\u305f</rt></ruby>\u3048\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u60c5<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u5831<rt>\u307b\u3046</rt></ruby><ruby>\u691c<rt>\u3051\u3093</rt></ruby><ruby>\u7d22<rt>\u3055\u304f</rt></ruby>\u306f<ruby>\u5927<rt>\u3060\u3044</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c1\u3064\u3042\u308a\u30012\u3064\u306e<ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u304c<ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<br>\n          <em>Pada Bagian 7 (Mondai 7), Anda akan membaca lembar pengumuman, pamflet, selebaran, poster, dan sejenisnya (sekitar 600 huruf), lalu menjawab pertanyaan mengenai isinya. Pencarian Informasi memiliki 1 materi utama dengan 2 pertanyaan.</em>\n        </p>\n        <p>\n          <strong>\u554f\u984c7</strong>\u3000\u53f3\u306e\u30da\u30fc\u30b8\uff08\u4e0b\u306e\u8cc7\u6599\uff09\u306f\u3001<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712\u306e\u30dd\u30b9\u30bf\u30fc\u3067\u3042\u308b\u3002\u3053\u308c\u3092\u8aad\u3093\u3067\u3001\u4e0b\u306e\u8cea\u554f\u306b\u7b54\u3048\u306a\u3055\u3044\u3002\u7b54\u3048\u306f\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br>\n          <em><strong>Soal 7:</strong> Materi di bawah ini adalah poster Taman Kereta Api. Bacalah poster ini, lalu jawablah pertanyaan di bawahnya. Pilihlah satu jawaban yang paling tepat dari pilihan 1, 2, 3, atau 4.</em>\n        </p>\n      </div>\n\n      <div class=\"practice-item\" id=\"info-retrieval-1\">\n        <div class=\"reading-passage notice-poster\">\n          <h5 style=\"text-align: center;\"><ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712 \u590f\u4f11\u307f\u3060\u3051\u306e\u7279\u5225\u30a4\u30d9\u30f3\u30c8\u306e\u304a\u77e5\u3089\u305b</h5>\n          <p style=\"text-align: center;\"><strong>\u30df\u30cb\u5217\u8eca\u30fb\u30e2\u30fc\u30ea\u30fc\u541b\u306b\u4e57\u308d\u3046\uff01</strong></p>\n\n          <p>\n            <strong>\u25c7\u65e5\u6642\uff1a</strong>7\u670821\u65e5\u300128\u65e5\u30018\u67084\u65e5\u30018\u670811\u65e5\u30018\u670818\u65e5<br>\n            17\uff1a30\u301c21\uff1a30\uff08\u6700\u7d42\u5165\u5712\u306f20\uff1a00\u307e\u3067\uff09<br>\n            \u203b\u3053\u306e\u65e5\u7a0b\u4ee5\u5916\u306f\u3001\u3044\u3064\u3082\u901a\u308a\u300117\u6642\u4ee5\u964d\u306f\u5165\u5712\u3067\u304d\u307e\u305b\u3093\u3002\n          </p>\n          <p>\n            <strong>\u25c7\u30e2\u30fc\u30ea\u30fc\u541b\u51fa\u767a\u6642\u9593</strong>\u3000\u246017\uff1a45\u301c\u3000\u246119\uff1a30\u301c<br>\n            \u4e57\u8eca\u306e\u6642\u9593\u306f\u51fa\u767a\u306e10\u5206\u524d\u307e\u3067\u3067\u3059\u3002<ruby>\u9045<rt>\u304a\u304f</rt></ruby>\u308c\u306a\u3044\u3088\u3046\u306b\u3001\u30e2\u30fc\u30ea\u30fc\u541b\u4e57\u308a\u5834\u306b\u96c6\u5408\u3057\u3066\u304f\u3060\u3055\u3044\u3002\n          </p>\n          <p>\n            <strong>\u25c7\u53c2\u52a0\u306e\u3057\u304b\u305f\uff1a</strong>\u663c\u9593\u3068\u540c\u3058\u5165\u5712\u6599\u304c\u304b\u304b\u308a\u307e\u3059\u3002<br>\n            \u30e2\u30fc\u30ea\u30fc\u541b\u306b\u4e57\u308b\u306b\u306f\u30c1\u30b1\u30c3\u30c8\u304c\u5fc5\u8981\u3067\u3059\u3002\u5165\u5712\u306e\u3068\u304d\u306b\u3001\u6b63\u9762\u5165\u308a\u53e3\u306e\u30c1\u30b1\u30c3\u30c8\u58f2\u308a\u5834\u3067\u5165\u5712\u6599\u3068\u4e57\u308a\u7269\u6599\u91d1\u3092\u5408\u308f\u305b\u305f\u6599\u91d1\u3092\u652f\u6255\u3063\u3066\u304f\u3060\u3055\u3044\u3002\n          </p>\n          <p>\n            <strong>\u25c7\u30ec\u30b9\u30c8\u30e9\u30f3\uff1a</strong>\u55b6\u696d\u3057\u3066\u3044\u307e\u3059\u3002\u30e2\u30fc\u30ea\u30fc\u541b\u306e\u8eca\u5185\u3067\u3082\u3001\u30e2\u30fc\u30ea\u30fc<ruby>\u5f01<rt>\u3079\u3093</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby>\u3001\u713c\u304d\u305d\u3070\u3001\u30aa\u30ec\u30f3\u30b8\u30b8\u30e5\u30fc\u30b9\u3001\u30b3\u30fc\u30d2\u30fc\u3001\u30a2\u30a4\u30b9\u30af\u30ea\u30fc\u30e0\u306a\u3069\u306e<ruby>\u8ca9<rt>\u306f\u3093</rt></ruby><ruby>\u58f2<rt>\u3070\u3044</rt></ruby>\u304c\u3042\u308a\u307e\u3059\u3002\n          </p>\n\n          <hr>\n          <p>\u307b\u304b\u306b\u3082<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u3092\u3082\u3063\u3068\u597d\u304d\u306b\u306a\u3063\u3066\u3082\u3089\u3046\u305f\u3081\u306e\u30a4\u30d9\u30f3\u30c8\u3092\u3001\u6bce\u9031\u958b\u3044\u3066\u3044\u307e\u3059\u3002</p>\n\n          <table class=\"info-table\">\n            <thead>\n              <tr>\n                <th>\u30a4\u30d9\u30f3\u30c8</th>\n                <th>\u5185\u5bb9\u30fb\u958b\u50ac\u65e5\u6642</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>A\u3000<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712\u6848\u5185</strong></td>\n                <td>\n                  \u5c02\u9580\u30b9\u30bf\u30c3\u30d5\u306e\u8a71\u3092\u805e\u304d\u306a\u304c\u3089\u3001\u30d0\u30b9\u306b\u4e57\u3063\u3066\u5712\u5185\u3092\u4e00\u5468\u3057\u307e\u3059\uff08\u7d0430\u5206\uff09\u3002<br>\n                  \u6614\u306e<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u306e\u3053\u3068\u3084\u3001\u96fb\u8eca\u306e<ruby>\u6b74<rt>\u308c\u304d</rt></ruby><ruby>\u53f2<rt>\u3057</rt></ruby>\u306b\u3064\u3044\u3066\u77e5\u308a\u307e\u3057\u3087\u3046\u3002<br>\n                  <strong>\u6bce\u65e5 3\u56de</strong>\u3000\u246010\uff1a30\uff5e\u3000\u246113\uff1a00\uff5e\u3000\u246215\uff1a30\uff5e\n                </td>\n              </tr>\n              <tr>\n                <td><strong>B\u3000\u99c5\u306e\u304a\u4ed5\u4e8b\u3092\u3084\u3063\u3066\u307f\u3088\u3046</strong></td>\n                <td>\n                  \u672c\u7269\u306e<ruby>\u5236<rt>\u305b\u3044</rt></ruby><ruby>\u670d<rt>\u3075\u304f</rt></ruby>\u3092\u7740\u3066\u3001\u99c5\u54e1\u306e\u4ed5\u4e8b\u3092\u3084\u3063\u3066\u307f\u307e\u3057\u3087\u3046\u3002<br>\n                  <strong>\u6bce\u9031 \u571f\u66dc</strong>\u300014\uff1a30\uff5e16\uff1a00\u3000\uff08\u4e88\u7d04\u304c\u5fc5\u8981\u3002\u4e00\u56de10\u4eba\u307e\u3067\u3002\uff09\n                </td>\n              </tr>\n              <tr>\n                <td><strong>C\u3000\u96fb\u8eca\u898b\u5b66</strong></td>\n                <td>\n                  \u5712\u5185\u306b\u3042\u308b\u5168\u3066\u306e\u96fb\u8eca\u306e\u8eca\u5185\u3092\u898b\u5b66\u3059\u308b\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002<br>\n                  \u666e\u6bb5\u306f\u898b\u3089\u308c\u306a\u3044\u3001\u30a8\u30f3\u30b8\u30f3\u306e\u4e2d\u3082\u516c\u958b\uff01<br>\n                  <strong>\u6bce\u9031 \u65e5\u66dc</strong>\u300013\uff1a30\uff5e15\uff1a30\n                </td>\n              </tr>\n              <tr>\n                <td><strong>D\u3000\u4ea4\u901a\u30eb\u30fc\u30eb\u6559\u5ba4</strong></td>\n                <td>\n                  \u96fb\u8eca\u306b\u3082\u4ea4\u901a\u30eb\u30fc\u30eb\u304c\u3042\u308a\u307e\u3059\u3002\u5712\u5185\u306b\u3042\u308b\u96fb\u8eca\u306e\u904b\u8ee2\u5e2d\u306b\u4e57\u3063\u3066\u3001<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u52c9\u5f37\u3057\u307e\u3057\u3087\u3046\u3002<br>\n                  <strong>\u6bce\u9031 \u6708\u66dc\u3001\u6728\u66dc</strong>\u300014\uff1a00\uff5e15\uff1a00<br>\n                  <strong>\u6bce\u9031 \u571f\u66dc</strong>\u3000\u3000\u3000\u300013\uff1a30\uff5e14\uff1a30\n                </td>\n              </tr>\n            </tbody>\n          </table>\n\n          <p>\n            <strong>\u53c2\u52a0\u6599\u91d1\uff1a</strong>\u7121\u6599<br>\n            <strong>\u96c6\u5408\u5834\u6240\uff1a</strong>A\u3001C\u3001D\uff1a\u6b63\u9762\u5165\u308a\u53e3\u3000B\uff1a<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712\u99c5\u5165\u308a\u53e3<br>\n            <strong>\u7533\u3057\u8fbc\u307f\uff1a</strong>B\u306e\u307f\u5f53\u65e512\u6642\u307e\u3067\u306b\u4e88\u7d04\u304c\u5fc5\u8981\u3067\u3059\u3002\u6b63\u9762\u5165\u308a\u53e3\u306e\u30c1\u30b1\u30c3\u30c8\u58f2\u308a\u5834\u3067\u4e88\u7d04\u3092\u53d7\u3051\u4ed8\u3051\u3066\u3044\u307e\u3059\u3002\n          </p>\n        </div>\n\n        <div class=\"passage-trans-box\">\n          <h4>Terjemahan Teks &amp; Poster:</h4>\n          <p style=\"text-align: center;\"><strong>Pemberitahuan Acara Khusus Liburan Musim Panas di Taman Kereta Api</strong><br>\n          <strong>Ayo Naik Kereta Mini \"Mori-kun\"!</strong></p>\n\n          <p>\n            <strong>\u25c7 Tanggal &amp; Waktu:</strong> 21 Juli, 28 Juli, 4 Agustus, 11 Agustus, 18 Agustus<br>\n            17.30-21.30 (Batas masuk taman terakhir sampai pukul 20.00)<br>\n            \u203b Selain tanggal-tanggal ini, seperti biasa, pengunjung tidak dapat masuk setelah pukul 17.00.\n          </p>\n          <p>\n            <strong>\u25c7 Jam Keberangkatan Mori-kun:</strong> \u2460 17.45-\u3000\u2461 19.30-<br>\n            Batas waktu naik kereta adalah 10 menit sebelum keberangkatan. Agar tidak terlambat, harap berkumpul di tempat naik (peron) Mori-kun.\n          </p>\n          <p>\n            <strong>\u25c7 Cara Berpartisipasi:</strong> Dikenakan biaya masuk taman yang sama seperti siang hari.<br>\n            Untuk naik Mori-kun diperlukan tiket. Saat masuk taman, silakan membayar gabungan biaya masuk dan tarif wahana di loket tiket pintu masuk utama.\n          </p>\n          <p>\n            <strong>\u25c7 Restoran:</strong> Tetap buka/beroperasi. Di dalam gerbong Mori-kun juga terdapat penjualan Mori Bento, yakisoba, jus jeruk, kopi, es krim, dan lain-lain.\n          </p>\n\n          <hr>\n          <p>Selain itu, kami juga mengadakan acara setiap minggu agar pengunjung semakin menyukai kereta api.</p>\n\n          <table class=\"info-table\">\n            <thead>\n              <tr>\n                <th>Acara</th>\n                <th>Isi Kegiatan &amp; Jadwal Pelaksanaan</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>A. Tur Panduan Taman Kereta Api</strong></td>\n                <td>\n                  Berkeliling area taman dengan menaiki bus sambil mendengarkan penjelasan dari staf ahli (sekitar 30 menit).<br>\n                  Mari mengenal tentang perkeretaapian masa lalu dan sejarah kereta listrik.<br>\n                  <strong>Setiap hari 3 kali:</strong> \u2460 10.30-\u3000\u2461 13.00-\u3000\u2462 15.30-\n                </td>\n              </tr>\n              <tr>\n                <td><strong>B. Ayo Coba Pekerjaan Stasiun</strong></td>\n                <td>\n                  Mari mencoba pekerjaan petugas stasiun dengan mengenakan seragam asli.<br>\n                  <strong>Setiap Sabtu:</strong> 14.30-16.00 (Perlu reservasi. Maksimal 10 orang per sesi.)\n                </td>\n              </tr>\n              <tr>\n                <td><strong>C. Kunjungan Kereta Listrik</strong></td>\n                <td>\n                  Anda dapat melihat-lihat bagian dalam seluruh gerbong kereta listrik yang ada di taman.<br>\n                  Bagian dalam mesin yang biasanya tidak terlihat juga dibuka untuk umum!<br>\n                  <strong>Setiap Minggu:</strong> 13.30-15.30\n                </td>\n              </tr>\n              <tr>\n                <td><strong>D. Kelas Aturan Lalu Lintas</strong></td>\n                <td>\n                  Kereta juga memiliki aturan lalu lintas. Mari belajar bersama sambil duduk di kursi masinis kereta yang ada di dalam taman.<br>\n                  <strong>Setiap Senin &amp; Kamis:</strong> 14.00-15.00<br>\n                  <strong>Setiap Sabtu:</strong> 13.30-14.30\n                </td>\n              </tr>\n            </tbody>\n          </table>\n\n          <p>\n            <strong>Biaya Partisipasi:</strong> Gratis<br>\n            <strong>Tempat Berkumpul:</strong> A, C, D: Pintu Masuk Utama | B: Pintu Masuk Stasiun Taman Kereta Api<br>\n            <strong>Pendaftaran:</strong> Khusus acara B memerlukan reservasi paling lambat pukul 12.00 pada hari yang sama. Reservasi diterima di loket tiket pintu masuk utama.\n          </p>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>1</strong>\u3000\u30a2\u30ea\u3055\u3093\u306f8\u67084\u65e5\u306b\u5a18\u3092<ruby>\u9023<rt>\u3064</rt></ruby>\u308c\u3066\u3001\u30e2\u30fc\u30ea\u30fc\u541b\u306b\u4e57\u308a\u305f\u3044\u3068\u601d\u3063\u3066\u3044\u308b\u3002\u30a2\u30ea\u3055\u3093\u304c\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3053\u3068\u306f\u3069\u308c\u304b\u3002<br>\n            <em>Sdr. Ali ingin mengajak putrinya naik Mori-kun pada tanggal 4 Agustus. Manakah hal yang harus dilakukan Sdr. Ali?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>19\uff1a30\u306b\u5a18\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u30e2\u30fc\u30ea\u30fc\u541b\u4e57\u308a\u5834\u3078\u884c\u304f\u3002<br><em>Pergi ke tempat naik Mori-kun bersama putrinya pada pukul 19.30.</em></li>\n            <li>\u5165\u5712\u6599\u3068\u4e57\u308a\u7269\u6599\u91d1\u3092\u30c1\u30b1\u30c3\u30c8\u58f2\u308a\u5834\u3067<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u652f\u6255\u3046\u3002<br><em>Membayar biaya masuk taman dan tarif wahana sekaligus di loket tiket.</em></li>\n            <li>\u5148\u306b\u5165\u5712\u6599\u3092\u6255\u3063\u3066\u3001\u30e2\u30fc\u30ea\u30fc\u541b\u4e57\u308a\u5834\u3067\u30c1\u30b1\u30c3\u30c8\u3092\u8cb7\u3046\u3002<br><em>Membayar biaya masuk taman terlebih dahulu, lalu membeli tiket di tempat naik Mori-kun.</em></li>\n            <li>\u30e2\u30fc\u30ea\u30fc\u541b\u306b\u4e57\u308b\u3068\u98df\u4e8b\u304c\u3067\u304d\u306a\u3044\u306e\u3067\u3001\u5148\u306b\u30ec\u30b9\u30c8\u30e9\u30f3\u3067\u98df\u4e8b\u3092\u3059\u308b\u3002<br><em>Karena tidak bisa makan setelah naik Mori-kun, makan di restoran terlebih dahulu.</em></li>\n          </ol>\n        </div>\n\n        <div class=\"question-block\">\n          <p class=\"question-text\">\n            <strong>2</strong>\u3000\u4eca\u65e5\u306f\u571f\u66dc\u65e5\u3067\u3042\u308b\u3002\u30e6\u30b9\u30e9\u3055\u3093\u306f13\u6642\u306b<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712\u306b\u6765\u305f\u3002\u3067\u304d\u308b\u3060\u3051\u305f\u304f\u3055\u3093\u306e\u30a4\u30d9\u30f3\u30c8\u306b\u53c2\u52a0\u3057\u305f\u3044\u3068\u601d\u3063\u3066\u3044\u308b\u304c\u3001<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u516c\u5712\u304c\u663c\u9593\u306b\u958b\u3044\u3066\u3044\u308b\u30a4\u30d9\u30f3\u30c8\u3067\u3001\u4eca\u304b\u3089\u53c2\u52a0\u3067\u304d\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002<br>\n            <em>Hari ini adalah hari Sabtu. Sdri. Yusra datang ke Taman Kereta Api pada pukul 13.00. Ia ingin mengikuti acara sebanyak mungkin; di antara acara yang dibuka Taman Kereta Api pada siang hari, manakah yang masih dapat ia ikuti mulai sekarang?</em>\n          </p>\n          <ol class=\"options-list\">\n            <li>A\u3060\u3051<br><em>Hanya A</em></li>\n            <li>B\u3068D<br><em>B dan D</em></li>\n            <li>A\u3068C\u3068D<br><em>A, C, dan D</em></li>\n            <li>A\u3068D<br><em>A dan D</em></li>\n          </ol>\n        </div>\n\n        <div class=\"answer-box\">\n          <p><strong>\u89e3\u8aac (Pembahasan):</strong></p>\n\n          <p><strong>1\u3000\u30a2\u30ea\u3055\u3093\u306f8<ruby>\u6708<rt>\u304c\u3064</rt></ruby><ruby>4<rt>\u3088\u3063\u304b</rt></ruby>\u65e5\u306b<ruby>\u5a18<rt>\u3080\u3059\u3081</rt></ruby>\u3092<ruby>\u9023<rt>\u3064</rt></ruby>\u308c\u3066\u3001\u30e2\u30fc\u30ea\u30fc<ruby>\u541b<rt>\u304f\u3093</rt></ruby>\u306b<ruby>\u4e57<rt>\u306e</rt></ruby>\u308a\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3063\u3066\u3044\u308b\u3002\u30a2\u30ea\u3055\u3093\u304c\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3053\u3068\u306f\u3069\u308c\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000<u>19\uff1a30</u>\u306b<ruby>\u5a18<rt>\u3080\u3059\u3081</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u30e2\u30fc\u30ea\u30fc<ruby>\u541b<rt>\u304f\u3093</rt></ruby><ruby>\u4e57<rt>\u306e</rt></ruby>\u308a<ruby>\u5834<rt>\u3070</rt></ruby>\u3078<ruby>\u884c<rt>\u3044</rt></ruby>\u304f\u3002\uff08\u00d7\uff09<br>10<ruby>\u5206<rt>\u3077\u3093</rt></ruby><ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306b<ruby>\u96c6<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u5408<rt>\u3054\u3046</rt></ruby>\u306a\u306e\u3067\u3001\u300c19\uff1a30\u300d\u3067\u306f\u306a\u304f\u300c19\uff1a20\u300d: <em>Karena harus berkumpul 10 menit sebelumnya, bukan pukul \"19.30\" melainkan pukul \"19.20\".</em></li>\n            <li><strong>2\u3000<ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3068<ruby>\u4e57<rt>\u306e</rt></ruby>\u308a<ruby>\u7269<rt>\u3082\u306e</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u91d1<rt>\u304d\u3093</rt></ruby>\u3092\u30c1\u30b1\u30c3\u30c8<ruby>\u58f2<rt>\u3046</rt></ruby>\u308a<ruby>\u5834<rt>\u3070</rt></ruby>\u3067<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b<ruby>\u652f<rt>\u3057</rt></ruby><ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046\u3002\uff08\u3007\uff09</strong>: <em>Jawaban Benar! (Pada bagian Cara Berpartisipasi tertulis pembayaran gabungan dilakukan di loket tiket pintu masuk utama saat masuk taman.)</em></li>\n            <li>3\u3000<u><ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u306b</u><ruby>\u5165<rt>\u306b\u3085\u3046</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby>\u3092<ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3063\u3066\u3001\u30e2\u30fc\u30ea\u30fc<ruby>\u541b<rt>\u304f\u3093</rt></ruby><ruby>\u4e57<rt>\u306e</rt></ruby>\u308a<ruby>\u5834<rt>\u3070</rt></ruby>\u3067\u30c1\u30b1\u30c3\u30c8\u3092<ruby>\u8cb7<rt>\u304b</rt></ruby>\u3046\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u306b\u300d\u3067\u306f\u306a\u304f\u3001<ruby>\u4e57<rt>\u306e</rt></ruby>\u308a<ruby>\u7269<rt>\u3082\u306e</rt></ruby><ruby>\u6599<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u91d1<rt>\u304d\u3093</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b<ruby>\u652f<rt>\u3057</rt></ruby><ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046: <em>Bukan membayar biaya masuk \"lebih dulu\", melainkan dibayar bersamaan dengan tarif wahana di loket tiket.</em></li>\n            <li>4\u3000\u30e2\u30fc\u30ea\u30fc<ruby>\u541b<rt>\u304f\u3093</rt></ruby>\u306b<ruby>\u4e57<rt>\u306e</rt></ruby>\u308b\u3068<u><ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u304c\u3067\u304d\u306a\u3044</u>\u306e\u3067\u3001<ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u306b\u30ec\u30b9\u30c8\u30e9\u30f3\u3067<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u3092\u3059\u308b\u3002\uff08\u00d7\uff09<br>\u300c<ruby>\u98df<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby>\u304c\u3067\u304d\u306a\u3044\u300d\u3068\u306f<ruby>\u8a00<rt>\u3044</rt></ruby>\u3063\u3066\u3044\u306a\u3044: <em>Di dalam teks tidak dikatakan \"tidak bisa makan\" (di dalam gerbong Mori-kun pun dijual bento, yakisoba, minuman, dan es krim).</em></li>\n          </ul>\n\n          <p><strong>2\u3000<ruby>\u4eca\u65e5<rt>\u304d\u3087\u3046</rt></ruby>\u306f<ruby>\u571f<rt>\u3069</rt></ruby><ruby>\u66dc<rt>\u3088\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u3067\u3042\u308b\u3002\u30e6\u30b9\u30e9\u3055\u3093\u306f13<ruby>\u6642<rt>\u3058</rt></ruby>\u306b<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby><ruby>\u516c<rt>\u3053\u3046</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby>\u306b<ruby>\u6765<rt>\u304d</rt></ruby>\u305f\u3002\u3067\u304d\u308b\u3060\u3051\u305f\u304f\u3055\u3093\u306e\u30a4\u30d9\u30f3\u30c8\u306b<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby>\u3057\u305f\u3044\u3068<ruby>\u601d<rt>\u304a\u3082</rt></ruby>\u3063\u3066\u3044\u308b\u304c\u3001<ruby>\u9244<rt>\u3066\u3064</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby><ruby>\u516c<rt>\u3053\u3046</rt></ruby><ruby>\u5712<rt>\u3048\u3093</rt></ruby>\u304c<ruby>\u663c<rt>\u3072\u308b</rt></ruby><ruby>\u9593<rt>\u307e</rt></ruby>\u306b<ruby>\u958b<rt>\u3042</rt></ruby>\u3044\u3066\u3044\u308b\u30a4\u30d9\u30f3\u30c8\u3067\u3001<ruby>\u4eca<rt>\u3044\u307e</rt></ruby>\u304b\u3089<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby>\u3067\u304d\u308b\u3082\u306e\u306f\u3069\u308c\u304b\u3002</strong></p>\n          <ul>\n            <li>1\u3000A<u>\u3060\u3051</u>\uff08\u00d7\uff09<br>D\u3082<ruby>\u53c2<rt>\u3055\u3093</rt></ruby><ruby>\u52a0<rt>\u304b</rt></ruby>\u3067\u304d\u308b: <em>Acara D juga dapat diikuti (hari Sabtu pukul 13.30-14.30; sedangkan acara A diadakan setiap hari termasuk pukul 13.00 dan 15.30).</em></li>\n            <li>2\u3000<u>B</u>\u3068D\uff08\u00d7\uff09<br>B\u306f<ruby>\u4e88<rt>\u3088</rt></ruby><ruby>\u7d04<rt>\u3084\u304f</rt></ruby>\u304c<ruby>\u5fc5<rt>\u3072\u3064</rt></ruby><ruby>\u8981<rt>\u3088\u3046</rt></ruby>: <em>Acara B memerlukan reservasi paling lambat pukul 12.00 pada hari yang sama (padahal Yusra datang pukul 13.00).</em></li>\n            <li>3\u3000A\u3068<u>C</u>\u3068D\uff08\u00d7\uff09<br>C\u306f<ruby>\u65e5<rt>\u306b\u3061</rt></ruby><ruby>\u66dc<rt>\u3088\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u306b<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u308f\u308c\u308b: <em>Acara C diselenggarakan pada hari Minggu (padahal hari ini adalah hari Sabtu).</em></li>\n            <li><strong>4\u3000A\u3068D\uff08\u3007\uff09</strong>: <em>Jawaban Benar!</em></li>\n          </ul>\n          <p class=\"correct-answer\"><strong><ruby>\u6b63<rt>\u305b\u3044</rt></ruby><ruby>\u7b54<rt>\u3068\u3046</rt></ruby> (Jawaban Benar): \u2460 2\u3000\u2461 4</strong></p>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n";
